INSERT INTO `email_template_langs` (`id`, `parent_id`, `language`, `subject`, `content`, `is_default`, `created_at`, `updated_at`) VALUES
(1, 1, 'ar', 'Order Complete', '<p>مرحبا ،</p><p>مرحبا بك في {app_name}.</p><p>مرحبا ، {order_id} ، شكرا للتسوق</p><p>لقد تلقينا طلب الشراء الخاص بك ، سنكون على اتصال بعد وقت قصير !</p><p>شكرا ،</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:07', '2026-06-09 21:39:07'),
(2, 1, 'da', 'Order Complete', '<p>Hej, &nbsp;</p><p>Velkommen til {app_name}.</p><p>Hej, {order_id}, Tak for din indkøbsanmodning</p><p>Vi har modtaget din købsanmodning.</p><p>Tak,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:07', '2026-06-09 21:39:07'),
(3, 1, 'de', 'Order Complete', '<p>Hallo, &nbsp;</p><p>Willkommen bei {app_name}.</p><p>Hi, {order_id}, Vielen Dank für Shopping</p><p>Wir haben Ihre Kaufanforderung erhalten, wir werden in Kürze in Kontakt sein!</p><p>Danke,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:07', '2026-06-09 21:39:07'),
(4, 1, 'en', 'Order Complete', '<p>Hello,&nbsp;</p><p>Welcome to {app_name}.</p><p>Hi, {order_id}, Thank you for Shopping</p><p>We received your purchase request, we\'ll be in touch shortly!</p><p>Thanks,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:07', '2026-06-09 21:39:07'),
(5, 1, 'es', 'Order Complete', '<p>Hola, &nbsp;</p><p>Bienvenido a {app_name}.</p><p>Hi, {order_id}, Thank you for Shopping</p><p>Recibimos su solicitud de compra, ¡estaremos en contacto en breve!</p><p>Gracias,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:07', '2026-06-09 21:39:07'),
(6, 1, 'fr', 'Order Complete', '<p>Bonjour, &nbsp;</p><p>Bienvenue dans {app_name}.</p><p>Hi, {order_id}, Thank you for Shopping</p><p>We reçus your purchase request, we \'ll be in touch incess!</p><p>Thanks,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:07', '2026-06-09 21:39:07'),
(7, 1, 'it', 'Order Complete', '<p>Ciao, &nbsp;</p><p>Benvenuti in {app_name}.</p><p>Ciao, {order_id}, Grazie per Shopping</p><p>Abbiamo ricevuto la tua richiesta di acquisto, noi \\ saremo in contatto a breve!</p><p>Grazie,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:07', '2026-06-09 21:39:07'),
(8, 1, 'ja', 'Order Complete', '<p>こんにちは &nbsp;</p><p>{app_name}にようこそ。</p><p>こんにちは、 {order_id}、ショッピング</p>ありがとうございます。</p><p>購入要求を受け取りました。すぐに連絡を取ります。</p><p>ありがとうございます。</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:07', '2026-06-09 21:39:07'),
(9, 1, 'nl', 'Order Complete', '<p>Hallo, &nbsp;</p><p>Welkom bij {app_name}.</p><p>Hallo, {order_id}, Dank u voor Winkelen</p><p>We hebben uw aankoopaanvraag ontvangen, we zijn binnenkort in contact!</p><p>Bedankt,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:07', '2026-06-09 21:39:07'),
(10, 1, 'pl', 'Order Complete', '<p>Witaj, &nbsp;</p><p>Witamy w aplikacji {app_name}.</p><p>Hi, {order_id}, Dziękujemy za zakupy</p><p>Otrzymamy Twój wniosek o zakup, wkrótce skontaktujemy się z Tobą!</p><p>Dzięki,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:07', '2026-06-09 21:39:07'),
(11, 1, 'ru', 'Order Complete', '<p>Hello, &nbsp;</p><p>Добро пожаловать в {app_name}.</p><p>Hi, {order_id}, Thank you for Shopping</p><p>Мы получили ваш запрос на покупку, мы \\ скоро свяжемся!</p><p>Thanks,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:07', '2026-06-09 21:39:07'),
(12, 1, 'pt', 'Order Complete', '<p>Olá, &nbsp;</p><p>Bem-vindo a {app_name}.</p><p>Oi, {order_id}, Obrigado por Shopping</p><p>Recebemos o seu pedido de compra, nós \\ estaremos em contato em breve!</p><p>Obrigado,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:07', '2026-06-09 21:39:07'),
(13, 1, 'zh', 'Order Complete', '<p>您好，</p><p>欢迎访问 {app_name}。</p><p>您好， {order_id}，感谢购物</p><p>我们收到您的购买请求，我们很快就会联系到 !</p><p>谢谢，</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:07', '2026-06-09 21:39:07'),
(14, 1, 'he', 'Order Complete', '<p>שלום, &nbsp;</p><p>ברוכים הבאים אל {app_name}.</p><p>היי, {order_id}, תודה על Shopping</p><p>קיבלנו את בקשת הרכש שלכם, נהיה בקשר בקרוב!</p><p>תודה,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:07', '2026-06-09 21:39:07'),
(15, 1, 'tr', 'Order Complete', '<p>Merhaba, &nbsp;</p><p>{app_name} olanağına hoş geldiniz.</p><p>Merhaba, {order_id}, Alışveriş için teşekkür ederiz</p><p>Satın alma talebinizi aldık, kısa süre içinde olacağız!</p><p>Teşekkürler,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(16, 1, 'pt-br', 'Order Complete', '<p>Olá, &nbsp;</p><p>Bem-vindo a {app_name}.</p><p>Oi, {order_id}, Obrigado por Shopping</p><p>Recebemos o seu pedido de compra, nós \\ estaremos em contato em breve!</p><p>Obrigado,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(17, 2, 'ar', 'Order Status', '<p>مرحبا ،</p><p>مرحبا بك في {app_name}.</p><p>الأمر الخاص بك هو {order_status} !</p><p>مرحبا {order_id} ، شكرا للتسوق</p><p>شكرا ،</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(18, 2, 'da', 'Order Status', '<p>Hej, &nbsp;</p><p>Velkommen til {app_name}.</p><p>Din ordre er {order_status}!</p><p>Hej {order_id}, Tak for at Shopping</p><p>Tak,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(19, 2, 'de', 'Order Status', '<p>Hello, &nbsp;</p><p>Willkommen bei {app_name}.</p><p>Ihre Bestellung lautet {order_status}!</p><p>Hi {order_id}, Danke für Shopping</p><p>Danke,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(20, 2, 'en', 'Order Status', '<p>Hello,&nbsp;</p><p>Welcome to {app_name}.</p><p>Your Order is {order_status}!</p><p>Hi {order_id}, Thank you for Shopping</p><p>Thanks,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(21, 2, 'es', 'Order Status', '<p>Hola, &nbsp;</p><p>Bienvenido a {app_name}.</p><p>Your Order is {order_status}!</p><p>Hi {order_id}, Thank you for Shopping</p><p>Thanks,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(22, 2, 'fr', 'Order Status', '<p>Bonjour, &nbsp;</p><p>Bienvenue dans {app_name}.</p><p>Votre commande est {order_status} !</p><p>Hi {order_id}, Thank you for Shopping</p><p>Thanks,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(23, 2, 'it', 'Order Status', '<p>Ciao, &nbsp;</p><p>Benvenuti in {app_name}.</p><p>Il tuo ordine è {order_status}!</p><p>Ciao {order_id}, Grazie per Shopping</p><p>Grazie,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(24, 2, 'ja', 'Order Status', '<p>こんにちは &nbsp;</p><p>{app_name}へようこそ</p><p>注文は {order_status}です。</p><p>ハイ・ {order_id}、<p>{app_name}</p><p><p>{order_url}</p></p><p>{app_name}</p>に感謝しています。</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(25, 2, 'nl', 'Order Status', '<p>Hallo, &nbsp;</p><p>Welkom bij {app_name}.</p><p>Uw bestelling is {order_status}!</p><p>Hi {order_id}, Dank u voor Winkelen</p><p>Bedankt,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(26, 2, 'pl', 'Order Status', '<p>Hello, &nbsp;</p><p>Witamy w aplikacji {app_name}.</p><p>Twoje zamówienie to {order_status}!</p><p>Hi {order_id}, Dziękujemy za zakupy</p><p>Thanks,</p><p>{app_name}</p><p>{order_url }</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(27, 2, 'ru', 'Order Status', '<p>Здравствуйте, &nbsp;</p><p>Вас приветствует {app_name}.</p><p>Ваш заказ-{order_status}!</p><p>Hi {order_id}, Thank you for Shopping</p><p>Thanks,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(28, 2, 'pt', 'Order Status', '<p>Olá, &nbsp;</p><p>Bem-vindo a {app_name}.</p><p>Sua Ordem é {order_status}!</p><p>Hi {order_id}, Obrigado por Shopping</p><p>Obrigado,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(29, 2, 'zh', 'Order Status', '<p>您好，</p><p>欢迎访问 {app_name}。</p><p>您的订单为 {order_status}!</p><p>Hi {order_id}，感谢购物</p><p>谢谢，</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(30, 2, 'he', 'Order Status', '<p>שלום, &nbsp;</p><p>ברוכים הבאים אל {app_name}.</p><p>ההזמנה שלכם היא {order_status}!</p><p>היי {order_id}, תודה על Shopping</p><p>תודה,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(31, 2, 'tr', 'Order Status', '<p>Merhaba, &nbsp;</p><p>{app_name} olanağına hoş geldiniz.</p><p>Siparişiniz {order_status}!</p><p>Merhaba {order_id}, Alışveriş için teşekkür ederiz</p><p>Teşekkürler,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(32, 2, 'pt-br', 'Order Status', '<p>Olá, &nbsp;</p><p>Bem-vindo a {app_name}.</p><p>Sua Ordem é {order_status}!</p><p>Hi {order_id}, Obrigado por Shopping</p><p>Obrigado,</p><p>{app_name}</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(33, 3, 'ar', 'Order Detail', '<p> مرحبًا ، </ p> <p> عزيزي {owner_name}. </p> <p> هذا أمر تأكيد {order_id} ضعه على <span style = \\\"font-size: 1rem؛\\\"> {order_date}. </span> </p> <p> شكرًا ، </ p> <p> {order_url} </p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(34, 3, 'da', 'Order Detail', '<p>Hej </p><p>Kære {owner_name}.</p><p>Dette er ordrebekræftelse {order_id} sted på <span style=\\\"font-size: 1rem;\\\">{order_date}. </span></p><p>Tak,</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(35, 3, 'de', 'Order Detail', '<p>Hallo, </p><p>Sehr geehrter {owner_name}.</p><p>Dies ist die Auftragsbestätigung {order_id}, die am <span style=\\\"font-size: 1rem;\\\">{order_date} aufgegeben wurde. </span></p><p>Danke,</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(36, 3, 'en', 'Order Detail', '<p>Hello,&nbsp;</p><p>Dear {owner_name}.</p><p>This is Confirmation Order {order_id} place on&nbsp;<span style=\\\"font-size: 1rem;\\\">{order_date}.</span></p><p>Thanks,</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(37, 3, 'es', 'Order Detail', '<p> Hola, </p> <p> Estimado {owner_name}. </p> <p> Este es el lugar de la orden de confirmación {order_id} en <span style = \\\"font-size: 1rem;\\\"> {order_date}. </span> </p> <p> Gracias, </p> <p> {order_url} </p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(38, 3, 'fr', 'Order Detail', '<p>Bonjour, </p><p>Cher {owner_name}.</p><p>Ceci est la commande de confirmation {order_id} passée le <span style=\\\"font-size: 1rem;\\\">{order_date}. </span></p><p>Merci,</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(39, 3, 'it', 'Order Detail', '<p>Ciao, </p><p>Gentile {owner_name}.</p><p>Questo è l\'ordine di conferma {order_id} effettuato su <span style=\\\"font-size: 1rem;\\\">{order_date}. </span></p><p>Grazie,</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(40, 3, 'ja', 'Order Detail', '<p>こんにちは、</ p> <p>親愛なる{owner_name}。</ p> <p>これは、<span style = \\\"font-size：1rem;\\\"> {order_date}の確認注文{order_id}の場所です。 </ span> </ p> <p>ありがとうございます</ p> <p> {order_url} </ p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(41, 3, 'nl', 'Order Detail', '<p>Hallo, </p><p>Beste {owner_name}.</p><p>Dit is de bevestigingsopdracht {order_id} die is geplaatst op <span style=\\\"font-size: 1rem;\\\">{order_date}. </span></p><p>Bedankt,</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(42, 3, 'pl', 'Order Detail', '<p>Witaj, </p><p>Drogi {owner_name}.</p><p>To jest potwierdzenie zamówienia {order_id} złożone na <span style=\\\"font-size: 1rem;\\\">{order_date}. </span></p><p>Dzięki,</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(43, 3, 'ru', 'Order Detail', '<p> Здравствуйте, </p> <p> Уважаемый {owner_name}. </p> <p> Это подтверждение заказа {order_id} на <span style = \\\"font-size: 1rem;\\\"> {order_date}. </span> </p> <p> Спасибо, </p> <p> {order_url} </p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(44, 3, 'pt', 'Order Detail', '<p> Térica-Dicas de Cadeia Pública de Тутутугальский (owner_name}). </p> <p> Тугальстугальстугальский (order_id} ний <span style = \\\" font-size: 1rem; \\ \"> {order_date}. </span> </p> <p> nome_do_chave de vida, </p> <p> {order_url} </p> <p> {order_url}', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(45, 3, 'zh', 'Order Detail', '<p>您好，</p><p>尊敬的 {owner_name}。</p><p>这是 \" font-size: 1rem;\\\">{order_date}上的 \" 确认订单 \" {order_id} 场所。</span></p><p>谢谢，</p><p>{order_url}</p>\"', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(46, 3, 'he', 'Order Detail', '<p>שלום, &nbsp;</p><p>היקר {owner_name}.</p><p>זוהי הזמנת אישור {order_id} מקום ב &nbsp; <span style= \\\" fontsize: 1rem;\\\"> {order_date}.</span></p><p>תודה,</p><p>{order_url}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(47, 3, 'tr', 'Order Detail', '<p>Merhaba, &nbsp;</p><p>Sayın {owner_name}.</p><p>Bu, &nbsp; <span style= \\\" font-size: 1rem; \\ \"> { order_date }.</span></p><p>Teşekkürler,</p><p>{order_url}</p>üzerinde bulunan Doğrulama Siparişi {order_id } yer', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(48, 3, 'pt-br', 'Order Detail', '<p> Térica-Dicas de Cadeia Pública de Тутутугальский (owner_name}). </p> <p> Тугальстугальстугальский (order_id} ний <span style = \\\" font-size: 1rem; \\ \"> {order_date}. </span> </p> <p> nome_do_chave de vida, </p> <p> {order_url} </p> <p> {order_url}', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(49, 4, 'ar', 'Stock Detail', '<p>مرحبا ،</p><p>عزيزي {customer_name}.</p><p>نحن متحمسون لاعلامك بأن المنتج الذي كنت تنتظره الآن قد عاد الى المخزن. لا تفوت هذه الفرصة للحصول على المعلومات الخاصة بك !</p><b>معلومات المنتج :</b><br><p>اسم المنتج : {product_name}</p><br><p>كود المنتج : {product_id}</p><p>شكرا ،</p><p>{app_name}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(50, 4, 'da', 'Stock Detail', '<p>Hej, &nbsp;</p><p>Kære {customer_name}.</p><p>Vi glæder os til at informere dig om, at det produkt, du har ventet på, nu er tilbage på lager. Gå ikke glip af denne mulighed for at få dine hænder på det!</p><b>Produktoplysninger:</b><br><p>Produktnavn: {product_name}</p><br><p>Produkt-id: {product_id}</p><p>Tak,</p><p>{app_name}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(51, 4, 'de', 'Stock Detail', '<p>Hallo, &nbsp;</p><p>Liebe {customer_name}.</p><p>Wir freuen uns darauf, Ihnen mitzuteilen, dass das Produkt, auf das Sie gewartet haben, jetzt wieder auf Lager ist. Verpassen Sie nicht diese Gelegenheit, um Ihre Hände dazu zu erhalten!</p><b>Produktinformationen:</b><br><p>Produktname: {product_name}</p><br><p>Produkt-ID: {product_id}</p><p>Danke,</p><p>{app_name}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(52, 4, 'en', 'Stock Detail', '<p>Hello,&nbsp;</p><p>Dear {customer_name}.</p><p>We are excited to inform you that the product you have been waiting for is now back in stock. Do not miss this opportunity to get your hands on it!</p><b>Product Information:</b><br><p>Product Name: {product_name}</p><br><p>Product Id:  {product_id}</p><p>Thanks,</p><p>{app_name}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(53, 4, 'es', 'Stock Detail', '<p>Hola, &nbsp;</p><p>Estimado {customer_name}.</p><p>Estamos entusiasmados de informarle de que el producto que ha estado esperando está ahora de nuevo en stock. No se pierda esta oportunidad de obtener las manos en él!</p><b>Información del producto:</b><br><p>Nombre del producto: {product_name}</p><br><p>Product Id: {product_id}</p><p>Thanks,</p><p>{app_name}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(54, 4, 'fr', 'Stock Detail', '<p>Bonjour, &nbsp;</p><p>Cher {customer_name}.</p><p>Nous sommes ravis de vous informer que le produit que vous attendez est maintenant de nouveau en stock. Ne manquez pas cette occasion de vous en procurer les mains !</p><b>Informations sur le produit:</b><br><p>Nom du produit: {product_name}</p><br><p>ID produit: {product_id}</p><p>Merci,</p><p>{app_name}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(55, 4, 'it', 'Stock Detail', '<p>Ciao, &nbsp;</p><p>Caro {customer_name}.</p><p>Siamo entusiici di informarti che il prodotto che hai atteso è ora tornato in stock. Non perderti questa opportunità di mettere le mani su!</p><b>Informazioni sul prodotto:</b><br><p>Nome prodotto: {product_name}</p><br><p>Id prodotto: {product_id}</p><p>Grazie,</p><p>{app_name}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(56, 4, 'ja', 'Stock Detail', '<p>Hello,&nbsp;</p><p>Dear {customer_name}.</p><p>お客様が待っていた製品が現在在庫に戻っていることをお知らせすることができます。 この機会を逃してはいけません。</p><b>製品情報:</b><br><p>製品名: {product_name}</p><br><p>製品 ID: {product_id}</p><p>ありがとうございます。</p><p>{app_name}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(57, 4, 'nl', 'Stock Detail', '<p>Hallo, &nbsp;</p><p>Beste {customer_name}.</p><p>We zijn enthousiast om u te informeren dat het product dat u hebt gewacht, nu weer op voorraad is. Mis deze kans niet om uw handen erop te krijgen!</p><b>Productinformatie:</b><br><p>Productnaam: {product_name}</p><br><p>Product-ID: {product_id}</p><p>Bedankt,</p><p>{app_name}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(58, 4, 'pl', 'Stock Detail', '<p>Hello, &nbsp;</p><p>Szanowny {customer_name}.</p><p>Jesteśmy podekscytowani informując, że produkt, na który czekałeś, jest teraz ponownie dostępny na magazynie. Nie przegap tej okazji, aby uzyskać na niej ręce!</p><b>Informacje o produkcie:</b><br><p>Nazwa produktu: {product_name}</p><br><p>Identyfikator produktu: {product_id}</p><p>Dzięki,</p><p>{app_name}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(59, 4, 'ru', 'Stock Detail', '<p>Здравствуйте, &nbsp;</p><p>Уважаемый пользователь {customer_name}.</p><p>Мы рады сообщить вам о том, что продукт, которого вы ждали, сейчас находится на складе. Не упустите эту возможность, чтобы получить от вас руки!</p><b>Информация о продукте:</b><br><p>Имя продукта: {product_name}</p><br><p>Product Id: {product_id}</p><p>Thanks,</p><p>{app_name}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(60, 4, 'pt', 'Stock Detail', '<p>Olá, &nbsp;</p><p>Dear {customer_name}.</p><p>Estamos entusiasmados em informar que o produto que você estava esperando está agora de volta em estoque. Não perca esta oportunidade de ficar com as mãos nele!</p><b>Informações do Produto:</b><br><p>Nome do Produto: {product_name}</p><br><p>Id do produto: {product_id}</p><p>Obrigado,</p><p>{app_name}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(61, 4, 'zh', 'Stock Detail', '<p>您好，</p><p>尊敬的 {customer_name}。</p><p>我们很高兴地通知您，您所等待的产品现在已恢复库存。 请不要错过此商机 !</p><b>产品信息:</b><br><p>产品名称: {product_name}</p><br><p>产品标识: {product_id}</p><p>谢谢，</p><p>{app_name}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(62, 4, 'tr', 'Stock Detail', '<p>Merhaba, &nbsp;</p><p>Sayın {customer_name}.</p><p>Beklediğiniz ürünün şu anda stokta geri dönmekte olduğunu size bildirmekten heyecan duyuyoruz. ellerinizi ona almak için bu fırsatı kaçırmayın!</p><b>ürün bilgileri:</b><br><p>ürün adı: {product_name}</p><br><p>Ürün Tanıtıcısı: {product_id}</p><p>Teşekkürler,</p><p>{app_name}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(63, 4, 'pt-br', 'Stock Detail', '<p>Olá, &nbsp;</p><p>Dear {customer_name}.</p><p>Estamos entusiasmados em informar que o produto que você estava esperando está agora de volta em estoque. Não perca esta oportunidade de ficar com as mãos nele!</p><b>Informações do Produto:</b><br><p>Nome do Produto: {product_name}</p><br><p>Id do produto: {product_id}</p><p>Obrigado,</p><p>{app_name}</p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(64, 5, 'ar', 'Abandon Cart', '<p>مرحبا&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">مرحبا بك في { app_name }.</span></p><p>لاحظنا أنك قمت مؤخرا بزيارة موقع { app_name } وقمت باضافة بعض البنود الرائعة الى عربة التسوق الخاصة بك. نحن مبتهجون بأنك وجدت منتجات تحبها ومع ذلك ، يبدو أنك لم تنهي عملية الشراء الخاصة بك والانتهاء من طلبك في أقرب وقت ممكن</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">معلومات منتج عربة الرسم :</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ cart_table }</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">شكرا</span></p><p>{ app_name }</p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(65, 5, 'da', 'Abandon Cart', '<p>Hallo?&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Velkommen til { app_name }.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Vi har bemærket, at du for nylig besøgte vores websted og tilføjede nogle fantastiske varer til indkøbsvognen. Vi er henrykte over, at du fandt produkter, du elsker! Men det ser ud til, at du ikke er færdig med dit køb.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Oplysninger om Cart-produkter:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ cart_table }</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Tak.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ app_name }</span></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(66, 5, 'de', 'Abandon Cart', '<p>Hallo,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Willkommen bei {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Wir haben bemerkt, dass Sie kürzlich unsere Website {app_name} besucht und einige fantastische Artikel in Ihren Warenkorb gelegt haben. Wir sind begeistert, dass Sie Produkte gefunden haben, die Sie lieben! Allerdings scheint es, als würden Sie Ihre Einkäufe nicht beenden. Sie beenden Ihren Bestellprozess so schnell wie möglich</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Warenkorb Produktinformation:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{cart_table}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Danke,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{Anwendungsname}</span></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(67, 5, 'en', 'Abandon Cart', '<p></p><p></p><p></p><p>Hello,&nbsp;</p><p>Welcome to {app_name}.</p><p><span style=\"text-align: var(--bs-body-text-align);\">We noticed that you recently visited our&nbsp;</span>{app_name}&nbsp;<span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">site and added some fantastic items to your shopping cart. We are thrilled that you found products you love! However, it seems like you did not finish your purchase.</span><span style=\"text-align: var(--bs-body-text-align);\">You finish your order process as soon as possible</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\"><br></span></p><span style=\"font-weight: 600;\">Cart Product Information:</span><p></p><p><span style=\"font-weight: 600;\"><br></span></p><p></p><p></p><p></p><p></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{cart_table}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\"><br></span></p><div><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Thanks,</span></p></div><p>{app_name}</p><p><br></p><p></p><p></p><p></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(68, 5, 'es', 'Abandon Cart', '<p>Hola,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Bienvenido a {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Hemos notado que recientemente ha visitado nuestro sitio {app_name} y ha añadido algunos artículos fantásticos a su carrito de la compra. ¡Estamos encantados de que encontraste productos que amas! Sin embargo, parece que usted no terminó su compra. Usted termina su proceso de pedido tan pronto como sea posible</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Información del producto del carro:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{cart_table}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Gracias,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(69, 5, 'fr', 'Abandon Cart', '<p>Bonjour,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Bienvenue dans { app_name }.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Nous avons remarqué que vous avez récemment visité notre site { app_name } et ajouté des articles fantastiques à votre panier. Nous sommes ravis que vous avez trouvé des produits que vous aimez ! Cependant, il semble que vous navez pas fini votre achat. Vous terminez votre commande dès que possible</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Cart Renseignements sur le produit:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ Table_cart_table }</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Merci,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ nom_app }</span></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(70, 5, 'it', 'Abandon Cart', '<p>Ciao,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Benvenuti in {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Abbiamo notato che recentemente hai visitato il nostro sito {app_name} e aggiunto alcuni articoli fantastici al tuo carrello. Siamo entusiasti di aver trovato dei prodotti che ami! Tuttavia, sembra che tu non abbia finito il tuo acquisto, finisci il tuo processo di ordine il prima possibile</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Informazioni sul prodotto del carrello:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{cart_table}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Grazie,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(71, 5, 'ja', 'Abandon Cart', '<p>こんにちは。&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}へようこそ。</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">最近、弊社の {app_name} サイトを訪問し、お客様のショッピング・カートに素晴らしいアイテムをいくつか追加しました。 あなたが愛する製品を見つけたと私たちはワクワクしている ! しかし、購入を完了していないようですが、できるだけ早く注文処理を完了します。</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">カート製品情報:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{cart_table}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">ありがとう。</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(72, 5, 'nl', 'Abandon Cart', '<p>Hallo,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Welkom bij { app_name }.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">We hebben gemerkt dat u onlangs onze site { app_name } hebt bezocht en enkele fantastische items aan uw winkelwagen heeft toegevoegd. We zijn blij dat je gevonden producten van je houdt! Echter, het lijkt alsof je niet klaar bent met uw aankoop. U klaar bent met uw bestelling proces zo snel mogelijk</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Productinformatie winkelwagen:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ order_tabel }</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Bedankt.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ app_name }</span></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(73, 5, 'pl', 'Abandon Cart', '<p>Witaj,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Witamy w aplikacji {app_name }.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Zauważyliśmy, że niedawno odwiedziliście naszą stronę {app_name } i dodaliśmy kilka fantastycznych pozycji do koszyka. Jesteśmy zachwyceni, że znalazłeś produkty, które kochasz! Jednak wydaje się, że nie skończyłaś swój zakup. Zakończ proces zamówienia tak szybko, jak to możliwe</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Informacje o produkcie koszyka:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{cart_table }</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Dziękuję,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name }</span></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(74, 5, 'ru', 'Abandon Cart', '<p>Привет.&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Вас приветствует { app_name }.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Мы заметили, что вы недавно посетили наш сайт { app_name } и добавили несколько фантастических предметов в вашу корзину. Мы в восторге от того, что вы нашли продукты, которые вы любите! Однако, похоже, вы не закончили свою покупку. Вы закончите процесс заказа как можно скорее</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Информация о продукте корзины:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ cart_table }</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Спасибо.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ имя_программы }</span></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(75, 5, 'pt', 'Abandon Cart', '<p>Olá,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Bem-vindo a {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Notamos que você visitou recentemente o nosso site {app_name} e adicionou alguns itens fantásticos ao seu carrinho de compras. Estamos emocionados por você ter encontrado produtos que você ama! No entanto, parece que você não terminou a sua compra, termina o seu processo de encomenda o mais rápido possível</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Informações do Produto do carrinho:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{cart_table}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Obrigado,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(76, 5, 'zh', 'Abandon Cart', '<p>你好， </p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">欢迎使用 {app_name}。</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">我们注意到您最近访问了我们的 {app_name} 站点，并将一些精彩项目添加到购物车。 我们很高兴你找到了爱的产品 但是，你好像没有完成你的购买，你尽快完成你的订单流程</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">购物车产品信息:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ cart_table}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">谢谢，</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ app_name}</span></p><div><br></div>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(77, 5, 'tr', 'Abandon Cart', '<p>Merhaba.&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ app_name } için hoş geldiniz.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Kısa bir süre önce { app_name } sitemizi ziyaret ettiniz ve alışveriş sepetinize bazı fantastik öğeler eklediğinizi fark ettik. Sevdiğiniz ürünleri bulmanıza sevindik! Ancak, satın alma işleminizi tamamlamamış gibi görünmektedir.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Alışveriş Sepeti Ürün Bilgileri:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ cart_table }</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Teşekkürler.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ uyg_adı }</span></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(78, 5, 'he', 'Abandon Cart', '<p>שלום,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">ברוכים הבאים אל {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">שמנו לב שלאחרונה ביקרת באתר שלנו ב - {app_name} והוספת כמה פריטים נפלאים לעגלת הקניות שלך. אנחנו שמחים שמצאת מוצרים שאתה אוהב! עם זאת, זה נראה כאילו לא סיימת את הרכישה שלך.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">פרטי מוצר של עגלה:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{cart_table}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">תודה,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(79, 5, 'pt-br', 'Abandon Cart', '<p>Olá,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Bem-vindo a {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Notamos que você visitou recentemente o nosso site {app_name} e adicionou alguns itens fantásticos ao seu carrinho de compras. Estamos emocionados por você ter encontrado produtos que você ama! No entanto, parece que você não terminou a sua compra, termina o seu processo de encomenda o mais rápido possível</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Informações do Produto do carrinho:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{cart_table}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Obrigado,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(80, 6, 'ar', 'Abandon Wishlist', '<p>مرحبا&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">مرحبا بك في { app_name }.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">لاحظنا أنك كنت تقوم بتصفح الموقع الخاص بنا وقمت باضافة بعض البنود المذهلة الى كشف wishlist الخاص بك. بسرعة ، بعض من هذه الأشياء ستباع بسرعة مع المخزون المحدود والطلب العالي ، الآن هو الوقت المثالي لجعل مشتريات حلمك.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">معلومات منتج كشف wishlist :</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ wislist_table }</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">شكرا</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ app_name }</span></p><p><br></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(81, 6, 'da', 'Abandon Wishlist', '<p>Hallo?&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Velkommen til { app_name }.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Vi har lagt mærke til, at du har gennemset vores hjemmeside og har tilføjet nogle fantastiske ting til din ønskeliste. Skynd dig, nogle af disse ting sælger hurtigt, og vi ville hade for dig at gå glip af dem. Med begrænset lager og høj efterspørgsel, er det nu det perfekte tidspunkt til at gøre dine drømme indkøb.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Oplysninger om ønskelisteoplysninger:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ wishlist_table }</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Tak.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ app_name }</span></p><p><br></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(82, 6, 'de', 'Abandon Wishlist', '<p>Hallo,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Willkommen bei {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Wir haben bemerkt, dass Sie unsere Website durchstöbern und einige fantastische Artikel zu Ihrer Wunschliste hinzugefügt haben. Beeilen Sie sich, einige dieser Artikel verkaufen sich schnell, und wir würden es hassen, dass Sie sie vermissen. Mit begrenztem Bestand und hoher Nachfrage ist jetzt die perfekte Zeit, um Ihre Traumkäufe zu tätigen.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Wishlist Produktinformation:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{wishlist_tabelle}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Danke,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{Anwendungsname}</span></p><p><br></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(83, 6, 'en', 'Abandon Wishlist', '<p>Hello,&nbsp;</p><p>Welcome to {app_name}.</p><p>We noticed that you have been browsing our site and have added some fantastic items to your wishlist. Hurry, some of these items are selling out fast. With limited stock and high demand, now is the perfect time to make your dream purchases.</p><p></p><p style=\"box-sizing: border-box; margin-top: 0px; margin-bottom: 1rem; font-size: 14px; color: rgb(0, 0, 0); font-family: \" open=\"\" sans\",=\"\" sans-serif;=\"\" font-style:=\"\" normal;=\"\" font-variant-ligatures:=\"\" font-variant-caps:=\"\" font-weight:=\"\" 400;=\"\" letter-spacing:=\"\" orphans:=\"\" 2;=\"\" text-align:=\"\" start;=\"\" text-indent:=\"\" 0px;=\"\" text-transform:=\"\" none;=\"\" white-space:=\"\" widows:=\"\" word-spacing:=\"\" -webkit-text-stroke-width:=\"\" text-decoration-thickness:=\"\" initial;=\"\" text-decoration-style:=\"\" text-decoration-color:=\"\" initial;\"=\"\"></p><p></p><p style=\"box-sizing: border-box; margin-top: 0px; margin-bottom: 1rem;\" open=\"\" sans\",=\"\" sans-serif;=\"\" font-style:=\"\" normal;=\"\" font-variant-ligatures:=\"\" font-variant-caps:=\"\" font-weight:=\"\" 400;=\"\" letter-spacing:=\"\" orphans:=\"\" 2;=\"\" text-align:=\"\" start;=\"\" text-indent:=\"\" 0px;=\"\" text-transform:=\"\" none;=\"\" white-space:=\"\" widows:=\"\" word-spacing:=\"\" -webkit-text-stroke-width:=\"\" text-decoration-thickness:=\"\" initial;=\"\" text-decoration-style:=\"\" text-decoration-color:=\"\" initial;\"=\"\"><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\"><b>Wishlist</b></span><span style=\"font-family: var(--bs-body-font-family); text-align: var(--bs-body-text-align); font-weight: 600;\">&nbsp;Product Information:</span></p><p open=\"\" sans\",=\"\" sans-serif;=\"\" font-style:=\"\" normal;=\"\" font-variant-ligatures:=\"\" font-variant-caps:=\"\" font-weight:=\"\" 400;=\"\" letter-spacing:=\"\" orphans:=\"\" 2;=\"\" text-align:=\"\" start;=\"\" text-indent:=\"\" 0px;=\"\" text-transform:=\"\" none;=\"\" white-space:=\"\" widows:=\"\" word-spacing:=\"\" -webkit-text-stroke-width:=\"\" text-decoration-thickness:=\"\" initial;=\"\" text-decoration-style:=\"\" text-decoration-color:=\"\" initial;\"=\"\"><span style=\"text-align: var(--bs-body-text-align);\">{wishlist_table}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Thanks,</span></p><p>{app_name}</p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(84, 6, 'es', 'Abandon Wishlist', '<p>Hola,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Bienvenido a {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Nos dimos cuenta de que has estado navegando por nuestro sitio y hemos añadido algunos artículos fantásticos a tu lista de deseos. Date prisa, algunos de estos artículos se están vendiendo rápido, y nos gustaría que te pierdas de ellos. Con un stock limitado y una alta demanda, ahora es el momento perfecto para hacer sus compras de ensueño.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Información del producto de lista de deseos:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{wishlist_table}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Gracias,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08');
INSERT INTO `email_template_langs` (`id`, `parent_id`, `language`, `subject`, `content`, `is_default`, `created_at`, `updated_at`) VALUES
(85, 6, 'fr', 'Abandon Wishlist', '<p>Bonjour,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Bienvenue dans { app_name }.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Nous avons remarqué que vous naviguez sur notre site et que vous avez ajouté des objets fantastiques à votre liste de cadeaux. Dépêchez, certains de ces objets se vendent vite, et nous vous haïrions de les manquer. Avec un stock limité et une forte demande, cest le moment idéal pour faire vos achats de rêve.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Wishlist Renseignements sur le produit:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ table_wishliste_wishs }</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Merci,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ nom_app }</span></p><p><br></p><p><br></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(86, 6, 'it', 'Abandon Wishlist', '<p>Ciao,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Benvenuti in {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Abbiamo notato che hai sfogliato il nostro sito e che hai aggiunto alcuni articoli fantastici alla tua wishlist. Svelto, alcuni di questi articoli si vendono in fretta, e odieremmo per farvi mancare su di loro. Con stock limitati e ad alta richiesta, ora è il momento perfetto per fare i tuoi acquisti da sogno.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">wishlist Informazioni sul prodotto:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{wishlist_table}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Grazie,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p><p><br></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(87, 6, 'ja', 'Abandon Wishlist', '<p>こんにちは。&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}へようこそ。</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">私たちは、あなたが私たちのサイトを閲覧していることに気付き、あなたの wishlistに素晴らしいアイテムを追加している 急いでこれらのアイテムの一部は売り切れですし、あなたが彼らを見逃すのを嫌っています 株式と需要が限られていることから、今は理想的な夢の購入に最適です。</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">wishlist 製品情報:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{wishlist_table}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">ありがとう。</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p><p><br></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(88, 6, 'nl', 'Abandon Wishlist', '<p>Hallo,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Welkom bij { app_name }.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">We hebben gemerkt dat u surfen op onze site en hebben enkele fantastische items toegevoegd aan uw wishlist. Snel, sommige van deze items verkopen snel. Met beperkte voorraad en hoge vraag, is nu de perfecte tijd om uw droom aankopen te maken.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">wishlist Productinformatie:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ wishlist_table }</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Bedankt.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ app_name }</span></p><p><br></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(89, 6, 'pl', 'Abandon Wishlist', '<p>Witaj,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Witamy w aplikacji {app_name }.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Zauważyliśmy, że przeglądałeś naszą stronę i dodaliśmy kilka fantastycznych przedmiotów do Twojej wiszliwi. Pospiesz się, niektóre z tych rzeczy sprzedają się szybko. Dzięki ograniczonym zapasom i wysokim popytem, teraz jest idealny czas na to, aby Twoje marzenie zakupów.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">wishlist Informacje o produkcie:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{wishlist_table }</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Dziękuję,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name }</span></p><p><br></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(90, 6, 'ru', 'Abandon Wishlist', '<p>Привет.&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Вас приветствует { app_name }.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Мы заметили, что вы просматриваете наш сайт и добавили в ваш список некоторые фантастические предметы. Поторопись, некоторые из этих предметов быстро продаются. С ограниченным западом и высоким спросом, сейчас идеальное время для того, чтобы совершить покупку мечты.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Информация о продукте wishlist:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ wishlist_table }</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Спасибо.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ имя_программы }</span></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(91, 6, 'pt', 'Abandon Wishlist', '<p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Olá, </span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Bem-vindo a {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Notamos que você tem navegado no nosso site e adicionamos alguns itens fantásticos à sua wishlist. Com pressa, alguns desses itens estão vendendo rápido. Com estoque limitado e alta demanda, agora é o momento perfeito para fazer as suas compras de sonho.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">wishlist Produto Informações:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{wishlist_table}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Obrigado,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(92, 6, 'zh', 'Abandon Wishlist', '<p>你好，&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">欢迎使用 {app_name}。</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">我们注意到您一直在浏览我们的站点，并已将一些精彩项目添加到您的 wishlist中。 快点这些物品有些卖得很快 拥有有限的股票和高需求，现在是实现梦想购买的完美时机。</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">wishlist 产品信息:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ wishlist_table}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">谢谢，</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ app_name}</span></p><p><br></p><div><br></div>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(93, 6, 'tr', 'Abandon Wishlist', '<p>Merhaba. </p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ app_name } için hoş geldiniz.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">sitemize göz attığınız ve wishlist e bazı fantastik öğeler eklediğinizi fark ettik. Acele edin, bu maddelerden bazıları hızlı satıyorlar. sınırlı hisse senedi ve yüksek talep ile artık hayalinizdeki satın alımlarınızı yapmak için mükemmel bir zaman.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">wishlist Ürün Bilgileri:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ wishlist_table }</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Teşekkürler.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{ uyg_adı }</span></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(94, 6, 'he', 'Abandon Wishlist', '<p>שלום,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">ברוכים הבאים אל {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">שמנו לב כי אתה כבר עיון באתר שלנו ויש הוסיף כמה פריטים נפלאים לרשימת המשאלות שלך. מהר, חלק מהפריטים האלה נמכרים מהר. עם מלאי מוגבל וביקוש גבוה, עכשיו זה הזמן המושלם לעשות רכישות החלום שלך.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">פרטי מוצר ברשימת wishlist:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{wishlist_table}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">תודה,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(95, 6, 'pt-br', 'Abandon Wishlist', '<p>Olá,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Bem-vindo a {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Notamos que você tem navegado no nosso site e adicionamos alguns itens fantásticos à sua wishlist. Com pressa, alguns desses itens estão vendendo rápido. Com estoque limitado e alta demanda, agora é o momento perfeito para fazer as suas compras de sonho.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">wishlist Produto Informações:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{wishlist_table}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Obrigado,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p>', 0, '2026-06-09 21:39:08', '2026-06-09 21:39:08'),
(96, 7, 'ar', 'Payment Reminder', '<p>عزيزي {customer_name}،<br /></p><p> هذا تذكير ودي بشأن الدفع الجزئي. </p><p> لقد استلمنا الدفعة الأولية بقيمة {amount} في {date} على الفور، ونحن نشكرك على ذلك.</p><p><br>يستحق الرصيد المتبقي بقيمة {remaining_amount} في {remaining_date} date.</p><p> يرجى التأكد من إتمام هذه الدفعة في الوقت المناسب لتجنب أي إزعاج.</p><p> شكرًا لك على تعاونك.</p>', 0, '2026-06-10 17:53:17', '2026-06-10 17:53:17'),
(97, 7, 'da', 'Payment Reminder', '<p>Kære {customer_name}<br /></p><p> Dette er en venlig påmindelse om delbetalingen. </p><p> Vi har modtaget den første betaling på {amount} den {date} omgående, hvilket vi takker dig for.</p><p><br>Den resterende saldo på {remaining_amount} forfalder i {remaining_date} dato.</p><p> Sørg for rettidig gennemførelse af denne betaling for at undgå ulejlighed.</p><p> Tak for dit samarbejde.</p>', 0, '2026-06-10 17:53:17', '2026-06-10 17:53:17'),
(98, 7, 'de', 'Payment Reminder', '<p>Sehr geehrter {customer_name},<br /></p><p> Dies ist eine freundliche Erinnerung an die Teilzahlung. </p><p>Wir haben die erste Zahlung in Höhe von {amount} am {date} umgehend erhalten, wofür wir uns bei Ihnen bedanken.</p><p><br>Der Restbetrag von {remaining_amount} ist fällig in {remaining_date} Datum.</p><p> Bitte stellen Sie sicher, dass diese Zahlung rechtzeitig abgeschlossen wird, um etwaige Unannehmlichkeiten zu vermeiden.</p><p> Vielen Dank für Ihre Kooperation.</p>', 0, '2026-06-10 17:53:17', '2026-06-10 17:53:17'),
(99, 7, 'en', 'Payment Reminder', '<p>Dear {customer_name},<br /></p><p> This is a friendly reminder about the partial payment. </p><p> We have received the initial payment of {amount} on {date} promptly, for which we thank you.</p><p><br>The remaining balance of {remaining_amount} is due in {remaining_date} date.</p><p> Please ensure timely completion of this payment to avoid any inconvenience.</p><p> Thank you for your cooperation.</p>', 0, '2026-06-10 17:53:17', '2026-06-10 17:53:17'),
(100, 7, 'es', 'Payment Reminder', '<p>Estimado {customer_name}:<br /></p><p> Este es un recordatorio amistoso sobre el pago parcial. </p><p>Hemos recibido el pago inicial de {amount} el {date} puntualmente, por lo que le agradecemos.</p><p><br>El saldo restante de {remaining_amount} vence en {remaining_date}.</p><p> Asegúrese de completar este pago a tiempo para evitar cualquier inconveniente.</p><p> Gracias por su cooperación.</p>', 0, '2026-06-10 17:53:17', '2026-06-10 17:53:17'),
(101, 7, 'fr', 'Payment Reminder', '<p>Cher {customer_name},<br /></p><p> Ceci est un rappel amical concernant le paiement partiel. </p><p> Nous avons reçu le paiement initial de {amount} le {date} dans les plus brefs délais, ce dont nous vous remercions.</p><p><br>Le solde restant de {remaining_amount} est dû dans {remaining_date} date.</p><p> Veuillez vous assurer deffectuer ce paiement dans les délais pour éviter tout inconvénient.</p><p> Merci de votre coopération.</p>', 0, '2026-06-10 17:53:17', '2026-06-10 17:53:17'),
(102, 7, 'it', 'Payment Reminder', '<p>Gentile {customer_name},<br /></p><p> Questo è un amichevole promemoria sul pagamento parziale. </p><p> Abbiamo ricevuto tempestivamente il pagamento iniziale di {amount} in data {date}, per questo ti ringraziamo.</p><p><br>Il saldo rimanente di {remaining_amount} è dovuto in {remaining_date} data.</p><p> Assicurati di completare tempestivamente questo pagamento per evitare eventuali inconvenienti.</p><p> Grazie per la collaborazione.</p>', 0, '2026-06-10 17:53:17', '2026-06-10 17:53:17'),
(103, 7, 'ja', 'Payment Reminder', '<p>{customer_name} 様<br /></p><p> 一部お支払いについてのお知らせです。 </p><p> {date} に最初の {amount} のお支払いを速やかに受け取りました。ありがとうございます。</p><p><br>{remaining_amount} の残りの残高は、{remaining_date}。 </p><p>ご迷惑を避けるため、この支払いは期限内に完了してください。</p><p>ご協力いただきありがとうございます。</p>', 0, '2026-06-10 17:53:17', '2026-06-10 17:53:17'),
(104, 7, 'nl', 'Payment Reminder', '<p>Beste {customer_name},<br /></p><p> Dit is een vriendelijke herinnering over de gedeeltelijke betaling. </p><p> We hebben de eerste betaling van {amount} snel ontvangen op {date}, waarvoor onze dank.</p><p><br>Het resterende saldo van {remaining_amount} moet over {remaining_date} datum.</p><p> Zorg ervoor dat u deze betaling tijdig voltooit om eventuele ongemakken te voorkomen.</p><p> Hartelijk dank voor uw medewerking.</p>', 0, '2026-06-10 17:53:17', '2026-06-10 17:53:17'),
(105, 7, 'pl', 'Payment Reminder', '<p>Szanowny {customer_name},<br /></p><p> To jest przyjazne przypomnienie o częściowej płatności. </p><p> Otrzymaliśmy niezwłocznie płatność początkową w wysokości {amount} w dniu {date}, za co dziękujemy.</p><p><br>Pozostałe saldo w wysokości {remaining_amount} należy uregulować w {remaining_date} data.</p><p> Prosimy o terminowe dokonanie tej płatności, aby uniknąć wszelkich niedogodności.</p><p> Dziękujemy za współpracę.</p>', 0, '2026-06-10 17:53:17', '2026-06-10 17:53:17'),
(106, 7, 'ru', 'Payment Reminder', '<p>Уважаемый {customer_name}!<br /></p><p> Это дружеское напоминание о частичной оплате. </p><p> Мы получили первоначальный платеж в размере {amount} {date} оперативно, за что благодарим вас.</p><p><br>Оставшийся остаток в размере {remaining_amount} подлежит оплате через {remaining_date} дата.</p><p> Пожалуйста, обеспечьте своевременное завершение этого платежа, чтобы избежать каких-либо неудобств.</p><p> Благодарим за сотрудничество.</p>', 0, '2026-06-10 17:53:17', '2026-06-10 17:53:17'),
(107, 7, 'pt', 'Payment Reminder', '<p>Prezado {customer_name},<br /></p><p> Este é um lembrete amigável sobre o pagamento parcial. </p><p> Recebemos o pagamento inicial de {amount} em {date} prontamente, pelo qual agradecemos.</p><p><br>O saldo restante de {remaining_amount} vence em {remaining_date} data.</p><p> Garanta a conclusão atempada deste pagamento para evitar qualquer inconveniente.</p><p> Obrigado pela sua cooperação.</p>', 0, '2026-06-10 17:53:17', '2026-06-10 17:53:17'),
(108, 7, 'zh', 'Payment Reminder', '<p>尊敬的{customer_name}，<br /></p><p>这是关于部分付款的友好提醒。 </p><p> 我们已于 {date} 立即收到 {amount} 的首期付款，对此我们表示感谢。</p><p><br>剩余的 {remaining_amount} 余额应于 {remaining_date}日期。</p><p>请确保及时完成此付款，以免造成任何不便。</p><p>感谢您的合作。</p>', 0, '2026-06-10 17:53:17', '2026-06-10 17:53:17'),
(109, 7, 'he', 'Payment Reminder', '<p>{customer_name} היקר,<br /></p><p> זוהי תזכורת ידידותית לגבי התשלום החלקי. </p><p> קיבלנו את התשלום הראשוני בסך {amount} בתאריך {date} באופן מיידי, ועל כך אנו מודים לך.</p><p><br>היתרה הנותרת בסך {remaining_amount} תגיע ב-{remaining_date}.</p><p> אנא הקפד להשלים בזמן של תשלום זה כדי למנוע אי נוחות.</p><p> תודה על שיתוף הפעולה.</p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(110, 7, 'tr', 'Payment Reminder', '<p>Sayın {customer_name},<br /></p><p> Bu, kısmi ödemeyle ilgili dostça bir hatırlatmadır. </p><p> {amount} tutarındaki ilk ödemeyi {date} tarihinde derhal aldık, bunun için size teşekkür ederiz.</p><p><br>Kalan {remaining_amount} bakiyesinin vadesi {remaining_date} tarihi.</p><p> Herhangi bir rahatsızlığı önlemek için lütfen bu ödemenin zamanında tamamlandığından emin olun.</p><p> İşbirliğiniz için teşekkür ederiz.</p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(111, 7, 'pt-br', 'Payment Reminder', '<p>Prezado {customer_name},<br /></p><p> Este é um lembrete amigável sobre o pagamento parcial. </p><p> Recebemos o pagamento inicial de {amount} em {date} prontamente, pelo qual agradecemos.</p><p><br>O saldo restante de {remaining_amount} vence em {remaining_date} data.</p><p> Garanta a conclusão atempada deste pagamento para evitar qualquer inconveniente.</p><p> Obrigado pela sua cooperação.</p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(112, 8, 'ar', 'Product Catelog', '<p>مرحبا </p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">مرحبا بك في {app_name}.</span></p><p>لاحظنا أنك قمت مؤخرا بزيارة موقع {app_name} وقمت باضافة بعض البنود الرائعة الى عربة التسوق الخاصة بك. نحن مبتهجون بأنك وجدت منتجات تحبها ومع ذلك ، يبدو أنك لم تنهي عملية الشراء الخاصة بك والانتهاء من طلبك في أقرب وقت ممكن</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">معلومات منتج عربة الرسم :</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{</span><span style=\"font-family: var(--bs-body-font-family); font-size: var(--bs-body-font-size); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{pdf_view}</span><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">شكرا</span></p><p>{app_name}</p><p><br></p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(113, 8, 'da', 'Product Catelog', '<p>Hallo?&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Velkommen til {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Vi har bemærket, at du for nylig besøgte vores websted og tilføjede nogle fantastiske varer til indkøbsvognen. Vi er henrykte over, at du fandt produkter, du elsker! Men det ser ud til, at du ikke er færdig med dit køb.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\"><br></span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Oplysninger om Cart-produkter:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\"><br></span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{pdf_view}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\"><br></span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Tak.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(114, 8, 'de', 'Product Catelog', '<p>Hallo,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Willkommen bei {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Wir haben bemerkt, dass Sie kürzlich unsere Website {app_name} besucht und einige fantastische Artikel in Ihren Warenkorb gelegt haben. Wir sind begeistert, dass Sie Produkte gefunden haben, die Sie lieben! Allerdings scheint es, als würden Sie Ihre Einkäufe nicht beenden. Sie beenden Ihren Bestellprozess so schnell wie möglich</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Warenkorb Produktinformation:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{pdf_view}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Danke,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(115, 8, 'en', 'Product Catelog', '<p>Hello, </p><p>Welcome to {app_name}.</p><p><span style=\"text-align: var(--bs-body-text-align);\">We noticed that you recently visited our </span>{app_name} <span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">site and added some fantastic items to your shopping cart. We are thrilled that you found products you love! However, it seems like you did not finish your purchase.</span><span style=\"text-align: var(--bs-body-text-align);\">You finish your order process as soon as possible</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\"><br></span></p><span style=\"font-weight: 600;\">Category Related Product Information:</span><p></p><p><span style=\"font-weight: 600;\"><br></span></p><p></p><p></p><p></p><p></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{pdf_view}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\"><br></span></p><div><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Thanks,</span></p></div><p>{app_name}</p>', 1, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(116, 8, 'es', 'Product Catelog', '<p>Hola,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Bienvenido a {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Hemos notado que recientemente ha visitado nuestro sitio {app_name} y ha añadido algunos artículos fantásticos a su carrito de la compra. ¡Estamos encantados de que encontraste productos que amas! Sin embargo, parece que usted no terminó su compra. Usted termina su proceso de pedido tan pronto como sea posible</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\"><br></span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Información del producto del carro:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{pdf_view}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\"><br></span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Gracias,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(117, 8, 'fr', 'Product Catelog', '<p>Bonjour,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Bienvenue dans {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Nous avons remarqué que vous avez récemment visité notre site {app_name} et ajouté des articles fantastiques à votre panier. Nous sommes ravis que vous avez trouvé des produits que vous aimez ! Cependant, il semble que vous navez pas fini votre achat. Vous terminez votre commande dès que possible</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\"><br></span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Cart Renseignements sur le produit:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{pdf_view}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\"><br></span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Merci,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(118, 8, 'it', 'Product Catelog', '<p>Ciao,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Benvenuti in {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Abbiamo notato che recentemente hai visitato il nostro sito {app_name} e aggiunto alcuni articoli fantastici al tuo carrello. Siamo entusiasti di aver trovato dei prodotti che ami! Tuttavia, sembra che tu non abbia finito il tuo acquisto, finisci il tuo processo di ordine il prima possibile</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\"><br></span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Informazioni sul prodotto del carrello:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{pdf_view}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\"><br></span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Grazie,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(119, 8, 'ja', 'Product Catelog', '<p>こんにちは。&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}へようこそ。</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">最近、弊社の {app_name} サイトを訪問し、お客様のショッピング・カートに素晴らしいアイテムをいくつか追加しました。 あなたが愛する製品を見つけたと私たちはワクワクしている ! しかし、購入を完了していないようですが、できるだけ早く注文処理を完了します。</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\"><br></span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">カート製品情報:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\"><br></span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{pdf_view}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\"><br></span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">ありがとう。</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(120, 8, 'nl', 'Product Catelog', '<p>Hallo,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Welkom bij {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">We hebben gemerkt dat u onlangs onze site {app_name} hebt bezocht en enkele fantastische items aan uw winkelwagen heeft toegevoegd. We zijn blij dat je gevonden producten van je houdt! Echter, het lijkt alsof je niet klaar bent met uw aankoop. U klaar bent met uw bestelling proces zo snel mogelijk</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Productinformatie winkelwagen:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{pdf_view}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Bedankt.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(121, 8, 'pl', 'Product Catelog', '<p>Witaj,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Witamy w aplikacji {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Zauważyliśmy, że niedawno odwiedziliście naszą stronę {app_name} i dodaliśmy kilka fantastycznych pozycji do koszyka. Jesteśmy zachwyceni, że znalazłeś produkty, które kochasz! Jednak wydaje się, że nie skończyłaś swój zakup. Zakończ proces zamówienia tak szybko, jak to możliwe</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Informacje o produkcie koszyka:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{pdf_view}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Dziękuję,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(122, 8, 'ru', 'Product Catelog', '<p>Привет.&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Вас приветствует {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Мы заметили, что вы недавно посетили наш сайт {app_name} и добавили несколько фантастических предметов в вашу корзину. Мы в восторге от того, что вы нашли продукты, которые вы любите! Однако, похоже, вы не закончили свою покупку. Вы закончите процесс заказа как можно скорее</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Информация о продукте корзины:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{pdf_view}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Спасибо.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(123, 8, 'pt', 'Product Catelog', '<p>Olá,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Bem-vindo a {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Notamos que você visitou recentemente o nosso site {app_name} e adicionou alguns itens fantásticos ao seu carrinho de compras. Estamos emocionados por você ter encontrado produtos que você ama! No entanto, parece que você não terminou a sua compra, termina o seu processo de encomenda o mais rápido possível</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Informações do Produto do carrinho:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{pdf_view}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Obrigado,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(124, 8, 'zh', 'Product Catelog', '<p>你好，</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">欢迎使用 {app_name}。</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">我们注意到您最近访问了我们的 {app_name} 站点，并将一些精彩项目添加到购物车。 我们很高兴你找到了爱的产品 但是，你好像没有完成你的购买，你尽快完成你的订单流程</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">购物车产品信息:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{pdf_view}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">谢谢，</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><div><br></div>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(125, 8, 'tr', 'Product Catelog', '<p>Merhaba.&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name} için hoş geldiniz.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Kısa bir süre önce {app_name} sitemizi ziyaret ettiniz ve alışveriş sepetinize bazı fantastik öğeler eklediğinizi fark ettik. Sevdiğiniz ürünleri bulmanıza sevindik! Ancak, satın alma işleminizi tamamlamamış gibi görünmektedir.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Alışveriş Sepeti Ürün Bilgileri:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{pdf_view}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Teşekkürler.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(126, 8, 'he', 'Product Catelog', '<p>שלום,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">ברוכים הבאים אל {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">שמנו לב שלאחרונה ביקרת באתר שלנו ב - {app_name} והוספת כמה פריטים נפלאים לעגלת הקניות שלך. אנחנו שמחים שמצאת מוצרים שאתה אוהב! עם זאת, זה נראה כאילו לא סיימת את הרכישה שלך.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">פרטי מוצר של עגלה:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{pdf_view}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">תודה,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(127, 8, 'pt-br', 'Product Catelog', '<p>Olá,&nbsp;</p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Bem-vindo a {app_name}.</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Notamos que você visitou recentemente o nosso site {app_name} e adicionou alguns itens fantásticos ao seu carrinho de compras. Estamos emocionados por você ter encontrado produtos que você ama! No entanto, parece que você não terminou a sua compra, termina o seu processo de encomenda o mais rápido possível</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Informações do Produto do carrinho:</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{pdf_view}</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">Obrigado,</span></p><p><span style=\"font-family: var(--bs-body-font-family); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">{app_name}</span></p><p><br></p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(128, 9, 'ar', 'Product Enquiry', '<p>عزيزي {customer_name}،<br />شكرًا لتواصلك معنا. لقد راجعنا استفسارك حول {product_name}، وإليك الرد على استفسارك:</p><p><strong>استعلامك</strong>: {product_query}</p><br /><p>< strong>ردنا</strong>: {product_answer}</p><p>إذا كانت لديك أية أسئلة أخرى أو كنت بحاجة إلى معلومات إضافية، فلا تتردد في إخبارنا بذلك.</p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(129, 9, 'da', 'Product Enquiry', '<p>Kære {customer_name},<br />Tak, fordi du kontaktede os! Vi har gennemgået din forespørgsel om {product_name}, og her er svaret på din forespørgsel:</p><p><strong>Din forespørgsel</strong>: {product_query}</p><br /><p>< strong>Vores svar</strong>: {product_answer}</p><p>Hvis du har yderligere spørgsmål eller brug for yderligere oplysninger, er du velkommen til at give os besked.</p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(130, 9, 'de', 'Product Enquiry', '<p>Sehr geehrter {customer_name},<br />Vielen Dank für Ihre Kontaktaufnahme! Wir haben Ihre Anfrage zu {product_name} überprüft und hier ist die Antwort auf Ihre Anfrage:</p><p><strong>Ihre Anfrage</strong>: {product_query}</p><br /><p>< strong>Unsere Antwort</strong>: {product_answer}</p><p>Wenn Sie weitere Fragen haben oder zusätzliche Informationen benötigen, lassen Sie es uns gerne wissen.</p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(131, 9, 'en', 'Product Enquiry', '<p>Dear {customer_name},<br />Thank you for reaching out! We have reviewed your enquiry about {product_name}, and here’s the response to your query:</p><p><strong>Your Query</strong>: {product_query}</p><br /><p><strong>Our Response</strong>: {product_answer}</p><p>If you have any further questions or need additional information, feel free to let us know.</p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(132, 9, 'es', 'Product Enquiry', '<p>Estimado {customer_name}:<br />¡Gracias por comunicarte! Hemos revisado su consulta sobre {product_name} y aquí está la respuesta a su consulta:</p><p><strong>Su consulta</strong>: {product_query}</p><br /><p>< strong>Nuestra respuesta</strong>: {product_answer}</p><p>Si tiene más preguntas o necesita información adicional, no dude en hacérnoslo saber.</p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(133, 9, 'fr', 'Product Enquiry', '<p>Cher {customer_name},<br />Merci de nous avoir contactés ! Nous avons examiné votre demande concernant {product_name} et voici la réponse à votre requête :</p><p><strong>Votre requête</strong> : {product_query}</p><br /><p>< strong>Notre réponse</strong> : {product_answer}</p><p>Si vous avez dautres questions ou avez besoin dinformations supplémentaires, nhésitez pas à nous le faire savoir.</p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(134, 9, 'it', 'Product Enquiry', '<p>Gentile {customer_name},<br />grazie per averci contattato! Abbiamo esaminato la tua richiesta su {product_name} ed ecco la risposta alla tua domanda:</p><p><strong>La tua domanda</strong>: {product_query}</p><br /><p>< strong>La nostra risposta</strong>: {product_answer}</p><p>Se hai ulteriori domande o hai bisogno di ulteriori informazioni, non esitare a farcelo sapere.</p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(135, 9, 'ja', 'Product Enquiry', '<p>{customer_name} 様<br />お問い合わせいただきありがとうございます。 {product_name} に関するお問い合わせを確認いたしました。</p><p><strong>あなたのクエリ</strong>: {product_query}</p><br /><p>< strong>弊社からの回答</strong>: {product_answer}</p><p>さらにご質問がある場合、または追加情報が必要な場合は、お気軽にお問い合わせください。</p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18');
INSERT INTO `email_template_langs` (`id`, `parent_id`, `language`, `subject`, `content`, `is_default`, `created_at`, `updated_at`) VALUES
(136, 9, 'nl', 'Product Enquiry', '<p>Beste {customer_name},<br />Bedankt dat u contact met ons opneemt! We hebben uw vraag over {product_name} beoordeeld en hier is het antwoord op uw vraag:</p><p><strong>Uw vraag</strong>: {product_query}</p><br /><p>< strong>Ons antwoord</strong>: {product_answer}</p><p>Als u nog vragen heeft of aanvullende informatie nodig heeft, kunt u ons dit laten weten.</p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(137, 9, 'pl', 'Product Enquiry', '<p>Szanowny {customer_name},<br />Dziękujemy za kontakt! Zapoznaliśmy się z Twoim zapytaniem dotyczącym produktu {product_name} i oto odpowiedź na Twoje pytanie:</p><p><strong>Twoje zapytanie</strong>: {product_query}</p><br /><p>< strong>Nasza odpowiedź</strong>: {product_answer}</p><p>Jeśli masz dalsze pytania lub potrzebujesz dodatkowych informacji, daj nam znać.</p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(138, 9, 'ru', 'Product Enquiry', '<p>Уважаемый {customer_name}!<br />Спасибо, что обратились к нам! Мы рассмотрели ваш запрос о {product_name} и вот ответ на ваш запрос:</p><p><strong>Ваш запрос</strong>: {product_query}</p><br /><p>< strong>Наш ответ</strong>: {product_answer}</p><p>Если у вас есть дополнительные вопросы или вам нужна дополнительная информация, сообщите нам об этом.</p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(139, 9, 'pt', 'Product Enquiry', '<p>Prezado {customer_name},<br />Obrigado por entrar em contato! Analisamos sua consulta sobre {product_name} e aqui está a resposta à sua consulta:</p><p><strong>Sua consulta</strong>: {product_query}</p><br /><p>< strong>Nossa resposta</strong>: {product_answer}</p><p>Se você tiver mais dúvidas ou precisar de informações adicionais, sinta-se à vontade para nos informar.</p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(140, 9, 'zh', 'Product Enquiry', '<p>尊敬的{customer_name}，<br />感谢您与我们联系！我们已审核您有关“{product_name}”的查询，现对您的查询进行回复：</p><p><strong>您的查询</strong>：{product_query}</p><br /><p>< strong>我们的回应</strong>：{product_answer}</p><p>如果您还有任何其他问题或需要其他信息，请随时告诉我们。</p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(141, 9, 'he', 'Product Enquiry', '<p>{customer_name} היקר,<br />תודה שפנית! בדקנו את שאלתך לגבי {product_name}, והנה התשובה לשאילתתך:</p><p><strong>השאילתה שלך</strong>: {product_query}</p><br /><p>< strong>התגובה שלנו</strong>: {product_answer}</p><p>אם יש לך שאלות נוספות או שאתה זקוק למידע נוסף, אל תהסס ליידע אותנו.</p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(142, 9, 'tr', 'Product Enquiry', '<p>Sayın {customer_name},<br />Bize ulaştığınız için teşekkür ederiz! {product_name} ile ilgili sorgunuzu inceledik ve sorunuzun yanıtını burada bulabilirsiniz:</p><p><strong>Sorgunuz</strong>: {product_query}</p><br /><p>< Strong>Yanıtımız</strong>: {product_answer}</p><p>Başka sorularınız varsa veya ek bilgiye ihtiyaç duyarsanız bize bildirmekten çekinmeyin.</p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(143, 9, 'pt-br', 'Product Enquiry', '<p>Prezado {customer_name},<br />Obrigado por entrar em contato! Analisamos sua consulta sobre {product_name} e aqui está a resposta à sua consulta:</p><p><strong>Sua consulta</strong>: {product_query}</p><br /><p>< strong>Nossa resposta</strong>: {product_answer}</p><p>Se você tiver mais dúvidas ou precisar de informações adicionais, sinta-se à vontade para nos informar.</p>', 0, '2026-06-10 17:53:18', '2026-06-10 17:53:18'),
(144, 10, 'ar', 'Order Review', '<p>عزيزي { customer_name } ،<br />شكرا لاختيارك { store_name }. نأمل أن تكون قد تم رضائك عن { store_name }.</p><p><strong>برجاء ترك التعليق التقييمي هنا</strong>: { review_url }</p><p>شكرا لك ، ونحن نتطلع لرؤيتك مرة أخرى في { app_name }.</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(145, 10, 'da', 'Order Review', '<p>Kære { customer_name },<br />Tak, fordi du har valgt { store_name }. Vi håber, at du er tilfreds med dit { store_name }.</p><p><strong>Vær venlig at give din feedback her</strong>: { review_url }</p><p>Tak, og vi ser frem til at se dig igen på { app_name }.</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(146, 10, 'de', 'Order Review', '<p>Liebe {customer_name},<br />Vielen Dank für die Auswahl von {store_name}. Wir hoffen, dass Sie mit Ihrem {store_name} zufrieden waren.</p><p><strong>Bitte hinterlassen Sie Ihr Feedback hier</strong>: {review_url}</p><p>Vielen Dank, und wir freuen uns darauf, Sie erneut unter {app_name} zu sehen.</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(147, 10, 'en', 'Order Review', '<p>Dear {customer_name},<br />Thank you for choosing {store_name}. We hope you were satisfied with your {store_name}.</p><p><strong>Please leave your feedback here</strong>: {review_url}</p><p>Thank you, and we look forward to seeing you again at {app_name}.</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(148, 10, 'es', 'Order Review', '<p>Estimado {customer_name},<br />Gracias por elegir {store_name}. Esperamos que esté satisfecho con su {store_name}.</p><p><strong>Por favor, deje sus comentarios aquí</strong>: {review_url}</p><p>Gracias, y esperamos volver a verlos en {app_name}.</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(149, 10, 'fr', 'Order Review', '<p>Cher { customer_name },<br />Merci davoir choisi { store_name }. Nous espérons que vous avez été satisfait de votre { store_name }.</p><p><strong>Veuillez laisser vos commentaires ici</strong>: { review_url }</p><p>Merci, et nous avons hâte de vous revoir à ladresse { app_name }.</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(150, 10, 'it', 'Order Review', '<p>Caro {customer_name},<br />Grazie per la scelta di {store_name}. Speriamo che tu fossi soddisfatto del tuo {store_name}.</p><p><strong>Ti prego di lasciare il tuo feedback qui</strong>: {revisw_url}</p><p>Grazie e non vediamo lora di rivederti a {app_name}.</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(151, 10, 'ja', 'Order Review', '<p>{ customer_name }、<br />{ store_name}を選択していただき、ありがとうございます。</p><p><strong>フィードバックをここにお送りください</strong>: {review_url}</p><p>ありがとうございます。また、 {app_name}で再度お客様にお会いできることをお待ちしています。</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(152, 10, 'nl', 'Order Review', '<p>Beste { customer_name },<br />Bedankt voor het kiezen van { store_name }. We hopen dat u tevreden bent met uw { store_name }.</p><p><strong>Laat uw feedback hier</strong>: { review_url }</p><p>Dank u, en we kijken ernaar uit u opnieuw te zien op { app_name }.</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(153, 10, 'pl', 'Order Review', '<p>Szanowny {customer_name },<br />Dziękujemy za wybranie {store_name }. Mamy nadzieję, że jesteś zadowolony z {store_name }.</p><p><strong>Proszę zostawić tu swoje opinie</strong>: {review_url }</p><p>Dziękujemy i czekamy na ponowne zobaczenie Cię w aplikacji {app_name }.</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(154, 10, 'ru', 'Order Review', '<p>Уважаемый пользователь { customer_name },<br />Спасибо, что вы выбрали { store_name }. Мы надеемся, что вас удовлетворит ваш { store_name }.</p><p><strong>Пожалуйста, оставьте свой отзыв здесь</strong>: { review_url }</p><p>Спасибо, и мы надеемся увидеть вас снова в { app_name }.</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(155, 10, 'pt', 'Order Review', '<p>Caros {customer_name},<br />Obrigado por escolher {store_name}. Esperamos que você tenha ficado satisfeito com o seu {store_name}.</p><p><strong>Deixe seu feedback aqui</strong>: {review_url}</p><p>Obrigado, e estamos ansiosos para vê-lo novamente em {app_name}.</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(156, 10, 'zh', 'Order Review', '<p>尊敬的 {customer_name}，<br />感谢您选择 {store_name}。我们希望您对 {store_name} 满意。</p><p><strong>请在此处留下您的反馈</strong>: {review_url}</p><p>谢谢，我们期待在 {app_name} 再次见到您。</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(157, 10, 'he', 'Order Review', '<p>היקר {customer_name},<br />תודה שבחרתם {store_name}. אנו מקווים שהייתם מסופקים עם {store_name}.</p><p><strong>אנא השאירו את המשוב שלכם כאן</strong>: {review_url}</p><p>תודה, ואנו מצפים לראות אתכם שוב ב - {app_name}.</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(158, 10, 'tr', 'Order Review', '<p>Sayın { customer_name },<br />{ store_name } ürününü seçtiğiniz için teşekkür ederiz. { store_name } mağazalarınızdan memnun olduğunuzu umuyoruz.</p><p><strong>Lütfen geribildiriminizi buraya bırakın</strong>: { review_url }</p><p>Teşekkür ederiz, ve sizi { app_name } içinde tekrar görmek için sabırsızlıkla bekliyoruz.</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(159, 10, 'pt-br', 'Order Review', '<p>Caros {customer_name},<br />Obrigado por escolher {store_name}. Esperamos que você tenha ficado satisfeito com o seu {store_name}.</p><p><strong>Deixe seu feedback aqui</strong>: {review_url}</p><p>Obrigado, e estamos ansiosos para vê-lo novamente em {app_name}.</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(160, 11, 'ar', 'Lucky Customer', '<p>عزيزي {customer_name}،<br />يسعدنا أن نعلن أنه تم اختيارك لتكون الفائز المحظوظ! وكتعبير عن تقديرنا، يسعدنا أن نقدم لك رمز قسيمة حصريًا يمكنك استخدامه أثناء الدفع لفتح التوفيرات الخاصة في عملية الشراء التالية.</p><p><strong>رمز القسيمة</strong>: {coupon_code}</p><br /><p><strong>تاريخ انتهاء الصلاحية</strong>: { coupon_expire_date}</p><p>أسرع، هذا العرض صالح لفترة محدودة فقط، لذا تأكد من استخدامه رمز القسيمة الخاص بك قبل انتهاء صلاحيته. تفضل بزيارة موقعنا على الويب {store_name} واستكشف مجموعتنا المثيرة من المنتجات. شكرًا لك على المشاركة، وتهانينا مرة أخرى على فوزك!</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(161, 11, 'da', 'Lucky Customer', '<p>Kære {customer_name},<br />Vi er glade for at kunne meddele, at du er blevet udvalgt som vores heldige vinder! Som et tegn på vores påskønnelse er vi glade for at kunne tilbyde dig en eksklusiv kuponkode, som du kan bruge under kassen for at låse op for særlige besparelser på dit næste køb.</p><p><strong>Kuponkode</strong>: { coupon_code}</p><br /><p><strong>Udløbsdato</strong>: {coupon_expire_date}</p><p>Skynd dig, dette tilbud er kun gyldigt i en begrænset periode, så sørg for at bruge din kuponkode, inden den udløber. Besøg vores hjemmeside {store_name} og udforsk vores spændende udvalg af produkter. Tak for din deltagelse, og endnu en gang tillykke med din sejr!</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(162, 11, 'de', 'Lucky Customer', '<p>Sehr geehrter {customer_name},<br />Wir freuen uns, Ihnen mitteilen zu können, dass Sie zu unserem glücklichen Gewinner gewählt wurden! Als Zeichen unserer Wertschätzung bieten wir Ihnen gerne einen exklusiven Gutscheincode an, mit dem Sie beim Bezahlvorgang besondere Ersparnisse bei Ihrem nächsten Einkauf freischalten können.</p><p><strong>Gutscheincode</strong>: {coupon_code}</p><br /><p><strong>Ablaufdatum</strong>: {coupon_expire_date}</p><p>Beeilen Sie sich, dieses Angebot ist nur für eine begrenzte Zeit gültig, also nutzen Sie es unbedingt Ihren Gutscheincode, bevor er abläuft. Besuchen Sie unsere Website {store_name} und entdecken Sie unser aufregendes Produktsortiment. Vielen Dank für Ihre Teilnahme und noch einmal herzlichen Glückwunsch zu Ihrem Gewinn!</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(163, 11, 'en', 'Lucky Customer', '<p>Dear {customer_name},<br />We are thrilled to announce that you have been selected as our lucky winner! As a token of our appreciation, we are delighted to offer you an exclusive coupon code that you can use during checkout to unlock special savings on your next purchase.</p><p><strong>Coupon Code</strong>: {coupon_code}</p><br /><p><strong>Expiration Date</strong>: {coupon_expire_date}</p><p>Hurry, this offer is valid for a limited time only, so make sure to use your coupon code before it expires. Visit our website {store_name} and explore our exciting range of products.Thank you for participating, and congratulations once again on your win!</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(164, 11, 'es', 'Lucky Customer', '<p>Estimado {customer_name}:<br />¡Estamos encantados de anunciar que ha sido seleccionado como nuestro afortunado ganador! Como muestra de nuestro agradecimiento, estamos encantados de ofrecerle un código de cupón exclusivo que puede utilizar durante el proceso de pago para desbloquear ahorros especiales en su próxima compra.</p><p><strong>Código de cupón</strong>: {coupon_code}</p><br /><p><strong>Fecha de vencimiento</strong>: {coupon_expire_date}</p><p>Apúrate, esta oferta es válida solo por tiempo limitado, así que asegúrate de usarla su código de cupón antes de que caduque. Visite nuestro sitio web {store_name} y explore nuestra interesante gama de productos. ¡Gracias por participar y felicidades una vez más por su victoria!</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(165, 11, 'fr', 'Lucky Customer', '<p>Cher {customer_name},<br />Nous sommes ravis dannoncer que vous avez été sélectionné comme notre heureux gagnant ! En guise de remerciement, nous sommes ravis de vous offrir un code promo exclusif que vous pouvez utiliser lors du paiement pour débloquer des économies spéciales sur votre prochain achat.</p><p><strong>Code promo</strong> : {coupon_code}</p><br /><p><strong>Date dexpiration</strong> : {coupon_expire_date}</p><p>Dépêchez-vous, cette offre est valable pour une durée limitée seulement, alors assurez-vous dutiliser votre code promo avant son expiration. Visitez notre site Web {store_name} et explorez notre gamme passionnante de produits. Merci davoir participé et félicitations encore une fois pour votre victoire !</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(166, 11, 'it', 'Lucky Customer', '<p>Caro {customer_name},<br />siamo entusiasti di annunciare che sei stato selezionato come nostro fortunato vincitore! In segno di apprezzamento, siamo lieti di offrirti un codice coupon esclusivo che puoi utilizzare durante il pagamento per sbloccare sconti speciali sul tuo prossimo acquisto.</p><p><strong>Codice coupon</strong>: {coupon_code}</p><br /><p><strong>Data di scadenza</strong>: {coupon_expire_date}</p><p>Affrettati, questa offerta è valida solo per un periodo di tempo limitato, quindi assicurati di utilizzarla il tuo codice coupon prima che scada. Visita il nostro sito web {store_name} ed esplora la nostra entusiasmante gamma di prodotti. Grazie per aver partecipato e congratulazioni ancora per la tua vincita!</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(167, 11, 'ja', 'Lucky Customer', '<p>{customer_name} 様<br />あなたが幸運な当選者に選ばれたことをお知らせできることを嬉しく思います。感謝の気持ちを込めて、チェックアウト時に使用すると、次回の購入時に特別な割引が得られる特別なクーポン コードを提供させていただきます。</p><p><strong>クーポン コード</strong>: {coupon_code}</p><br /><p><strong>有効期限</strong>: {coupon_expire_date}</p><p>お急ぎください。この特典は期間限定ですので、必ずご利用ください。有効期限が切れる前にクーポンコードを取得してください。当社のウェブサイト {store_name} にアクセスして、幅広い製品をご覧ください。ご参加いただきありがとうございます。そして、改めて優勝おめでとうございます!</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(168, 11, 'nl', 'Lucky Customer', '<p>Beste {customer_name},<br />Met veel plezier kondigen wij aan dat u bent geselecteerd als onze gelukkige winnaar! Als blijk van onze waardering bieden we u graag een exclusieve couponcode aan die u tijdens het afrekenen kunt gebruiken om speciale kortingen te ontgrendelen op uw volgende aankoop.</p><p><strong>Couponcode</strong>: {coupon_code}</p><br /><p><strong>Vervaldatum</strong>: {coupon_expire_date}</p><p>Schiet op, deze aanbieding is slechts een beperkte tijd geldig, dus zorg ervoor dat u deze gebruikt uw couponcode voordat deze verloopt. Bezoek onze website {store_name} en ontdek ons ​​opwindende assortiment. Bedankt voor uw deelname en nogmaals gefeliciteerd met uw overwinning!</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(169, 11, 'pl', 'Lucky Customer', '<p>Drogi {customer_name},<br />Z radością ogłaszamy, że zostałeś wybrany naszym szczęśliwym zwycięzcą! W dowód naszego uznania z przyjemnością oferujemy Ci ekskluzywny kod kuponu, którego możesz użyć podczas realizacji transakcji, aby odblokować specjalne oszczędności przy następnym zakupie.</p><p><strong>Kod kuponu</strong>: { coupon_code</p><br /><p><strong>Data ważności</strong>: {coupon_expire_date}</p><p>Pospiesz się, ta oferta jest ważna tylko przez ograniczony czas, więc pamiętaj, aby skorzystać swój kod kuponu przed jego wygaśnięciem. Odwiedź naszą stronę internetową {store_name} i poznaj naszą ekscytującą gamę produktów. Dziękujemy za udział i jeszcze raz gratulujemy wygranej!</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(170, 11, 'ru', 'Lucky Customer', '<p>Уважаемый {customer_name}!<br />Мы рады сообщить, что вы стали нашим счастливым победителем! В знак нашей признательности мы рады предложить вам эксклюзивный код купона, который вы можете использовать при оформлении заказа, чтобы получить специальную скидку на следующую покупку.</p><p><strong>Код купона</strong>: {coupon_code}</p><br /><p><strong>Дата истечения срока действия</strong>: {coupon_expire_date}</p><p>Спешите, это предложение действительно только в течение ограниченного времени, поэтому обязательно воспользуйтесь ваш код купона до истечения срока его действия. Посетите наш веб-сайт {store_name} и изучите наш потрясающий ассортимент товаров. Благодарим за участие и еще раз поздравляем с победой!</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(171, 11, 'pt', 'Lucky Customer', '<p>Prezado {customer_name},<br />Temos o prazer de anunciar que você foi selecionado como nosso sortudo vencedor! Como forma de agradecimento, temos o prazer de oferecer a você um código de cupom exclusivo que você pode usar durante a finalização da compra para desbloquear descontos especiais em sua próxima compra.</p><p><strong>Código de cupom</strong>: {coupon_code}</p><br /><p><strong>Data de validade</strong>: {coupon_expire_date}</p><p>Depressa, esta oferta é válida apenas por tempo limitado, então certifique-se de usar seu código de cupom antes que ele expire. Visite nosso site {store_name} e explore nossa incrível variedade de produtos. Obrigado por participar e parabéns mais uma vez pela sua vitória!</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(172, 11, 'zh', 'Lucky Customer', '<p>尊敬的{customer_name}，<br />我们很高兴地宣布您已被选为我们的幸运获奖者！为了表达我们的谢意，我们很高兴为您提供专属优惠券代码，您可以在结账时使用该代码，以便在下次购买时享受特别优惠。</p><p><strong>优惠券代码</strong>：{coupon_code}</p><br /><p><strong>到期日期</strong>：{coupon_expire_date}</p><p>快点，此优惠仅在有限时间内有效，因此请务必使用您的优惠券代码在过期之前。请访问我们的网站 {store_name} 并探索我们令人兴奋的产品系列。感谢您的参与，并再次祝贺您获奖！</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(173, 11, 'he', 'Lucky Customer', '<p>{customer_name} היקר,<br />אנו שמחים להודיע ​​שנבחרת כזוכה המאושר שלנו! כאות להערכתנו, אנו שמחים להציע לך קוד קופון בלעדי שבו תוכל להשתמש במהלך התשלום כדי לשחרר חיסכון מיוחד ברכישה הבאה שלך.</p><p><strong>קוד קופון</strong>: {coupon_code}</p><br /><p><strong>תאריך תפוגה</strong>: {coupon_expire_date}</p><p>מהר, מבצע זה תקף לזמן מוגבל בלבד, אז הקפד להשתמש קוד הקופון שלך לפני שהוא יפוג. בקר באתר האינטרנט שלנו {store_name} וחקור את מגוון המוצרים המרגש שלנו. תודה לך על ההשתתפות, ושוב מזל טוב על הזכייה שלך!</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(174, 11, 'tr', 'Lucky Customer', '<p>Sayın {customer_name},<br />Şanslı talihlimiz olarak seçildiğinizi duyurmaktan büyük heyecan duyuyoruz! Takdirimizin bir göstergesi olarak, bir sonraki satın alma işleminizde özel indirimlerin kilidini açmak için ödeme sırasında kullanabileceğiniz özel bir kupon kodunu size sunmaktan mutluluk duyuyoruz.</p><p><strong>Kupon Kodu</strong>: {coupon_code}</p><br /><p><strong>Son Kullanma Tarihi</strong>: {coupon_expire_date}</p><p>Acele edin, bu teklif yalnızca sınırlı bir süre için geçerlidir, bu nedenle mutlaka kullanın Kupon kodunuzun süresi dolmadan. {store_name} web sitemizi ziyaret edin ve heyecan verici ürün yelpazemizi keşfedin. Katıldığınız için teşekkür ederiz ve kazandığınız için bir kez daha tebrik ederiz!</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(175, 11, 'pt-br', 'Lucky Customer', '<p>Prezado {customer_name},<br />Temos o prazer de anunciar que você foi selecionado como nosso sortudo vencedor! Como forma de agradecimento, temos o prazer de oferecer a você um código de cupom exclusivo que você pode usar durante a finalização da compra para desbloquear descontos especiais em sua próxima compra.</p><p><strong>Código de cupom</strong>: {coupon_code}</p><br /><p><strong>Data de validade</strong>: {coupon_expire_date}</p><p>Depressa, esta oferta é válida apenas por tempo limitado, então certifique-se de usar seu código de cupom antes que ele expire. Visite nosso site {store_name} e explore nossa incrível variedade de produtos. Obrigado por participar e parabéns mais uma vez pela sua vitória!</p>', 0, '2026-06-10 17:53:19', '2026-06-10 17:53:19'),
(176, 12, 'ar', 'Payment Reminder', '<p>عزيزي {customer_name}،<br /></p><p> هذا تذكير ودي بشأن الدفع الجزئي. </p><p> لقد استلمنا الدفعة الأولية بقيمة {amount} في {date} على الفور، ونحن نشكرك على ذلك.</p><p><br>يستحق الرصيد المتبقي بقيمة {remaining_amount} في {remaining_date} date.</p><p> يرجى التأكد من إتمام هذه الدفعة في الوقت المناسب لتجنب أي إزعاج.</p><p> شكرًا لك على تعاونك.</p>', 0, '2026-07-30 12:06:45', '2026-07-30 12:06:45'),
(177, 12, 'da', 'Payment Reminder', '<p>Kære {customer_name}<br /></p><p> Dette er en venlig påmindelse om delbetalingen. </p><p> Vi har modtaget den første betaling på {amount} den {date} omgående, hvilket vi takker dig for.</p><p><br>Den resterende saldo på {remaining_amount} forfalder i {remaining_date} dato.</p><p> Sørg for rettidig gennemførelse af denne betaling for at undgå ulejlighed.</p><p> Tak for dit samarbejde.</p>', 0, '2026-07-30 12:06:45', '2026-07-30 12:06:45'),
(178, 12, 'de', 'Payment Reminder', '<p>Sehr geehrter {customer_name},<br /></p><p> Dies ist eine freundliche Erinnerung an die Teilzahlung. </p><p>Wir haben die erste Zahlung in Höhe von {amount} am {date} umgehend erhalten, wofür wir uns bei Ihnen bedanken.</p><p><br>Der Restbetrag von {remaining_amount} ist fällig in {remaining_date} Datum.</p><p> Bitte stellen Sie sicher, dass diese Zahlung rechtzeitig abgeschlossen wird, um etwaige Unannehmlichkeiten zu vermeiden.</p><p> Vielen Dank für Ihre Kooperation.</p>', 0, '2026-07-30 12:06:45', '2026-07-30 12:06:45'),
(179, 12, 'en', 'Payment Reminder', '<p>Dear {customer_name},<br /></p><p> This is a friendly reminder about the partial payment. </p><p> We have received the initial payment of {amount} on {date} promptly, for which we thank you.</p><p><br>The remaining balance of {remaining_amount} is due in {remaining_date} date.</p><p> Please ensure timely completion of this payment to avoid any inconvenience.</p><p> Thank you for your cooperation.</p>', 0, '2026-07-30 12:06:45', '2026-07-30 12:06:45'),
(180, 12, 'es', 'Payment Reminder', '<p>Estimado {customer_name}:<br /></p><p> Este es un recordatorio amistoso sobre el pago parcial. </p><p>Hemos recibido el pago inicial de {amount} el {date} puntualmente, por lo que le agradecemos.</p><p><br>El saldo restante de {remaining_amount} vence en {remaining_date}.</p><p> Asegúrese de completar este pago a tiempo para evitar cualquier inconveniente.</p><p> Gracias por su cooperación.</p>', 0, '2026-07-30 12:06:45', '2026-07-30 12:06:45'),
(181, 12, 'fr', 'Payment Reminder', '<p>Cher {customer_name},<br /></p><p> Ceci est un rappel amical concernant le paiement partiel. </p><p> Nous avons reçu le paiement initial de {amount} le {date} dans les plus brefs délais, ce dont nous vous remercions.</p><p><br>Le solde restant de {remaining_amount} est dû dans {remaining_date} date.</p><p> Veuillez vous assurer deffectuer ce paiement dans les délais pour éviter tout inconvénient.</p><p> Merci de votre coopération.</p>', 0, '2026-07-30 12:06:45', '2026-07-30 12:06:45'),
(182, 12, 'it', 'Payment Reminder', '<p>Gentile {customer_name},<br /></p><p> Questo è un amichevole promemoria sul pagamento parziale. </p><p> Abbiamo ricevuto tempestivamente il pagamento iniziale di {amount} in data {date}, per questo ti ringraziamo.</p><p><br>Il saldo rimanente di {remaining_amount} è dovuto in {remaining_date} data.</p><p> Assicurati di completare tempestivamente questo pagamento per evitare eventuali inconvenienti.</p><p> Grazie per la collaborazione.</p>', 0, '2026-07-30 12:06:45', '2026-07-30 12:06:45'),
(183, 12, 'ja', 'Payment Reminder', '<p>{customer_name} 様<br /></p><p> 一部お支払いについてのお知らせです。 </p><p> {date} に最初の {amount} のお支払いを速やかに受け取りました。ありがとうございます。</p><p><br>{remaining_amount} の残りの残高は、{remaining_date}。 </p><p>ご迷惑を避けるため、この支払いは期限内に完了してください。</p><p>ご協力いただきありがとうございます。</p>', 0, '2026-07-30 12:06:45', '2026-07-30 12:06:45'),
(184, 12, 'nl', 'Payment Reminder', '<p>Beste {customer_name},<br /></p><p> Dit is een vriendelijke herinnering over de gedeeltelijke betaling. </p><p> We hebben de eerste betaling van {amount} snel ontvangen op {date}, waarvoor onze dank.</p><p><br>Het resterende saldo van {remaining_amount} moet over {remaining_date} datum.</p><p> Zorg ervoor dat u deze betaling tijdig voltooit om eventuele ongemakken te voorkomen.</p><p> Hartelijk dank voor uw medewerking.</p>', 0, '2026-07-30 12:06:45', '2026-07-30 12:06:45'),
(185, 12, 'pl', 'Payment Reminder', '<p>Szanowny {customer_name},<br /></p><p> To jest przyjazne przypomnienie o częściowej płatności. </p><p> Otrzymaliśmy niezwłocznie płatność początkową w wysokości {amount} w dniu {date}, za co dziękujemy.</p><p><br>Pozostałe saldo w wysokości {remaining_amount} należy uregulować w {remaining_date} data.</p><p> Prosimy o terminowe dokonanie tej płatności, aby uniknąć wszelkich niedogodności.</p><p> Dziękujemy za współpracę.</p>', 0, '2026-07-30 12:06:45', '2026-07-30 12:06:45'),
(186, 12, 'ru', 'Payment Reminder', '<p>Уважаемый {customer_name}!<br /></p><p> Это дружеское напоминание о частичной оплате. </p><p> Мы получили первоначальный платеж в размере {amount} {date} оперативно, за что благодарим вас.</p><p><br>Оставшийся остаток в размере {remaining_amount} подлежит оплате через {remaining_date} дата.</p><p> Пожалуйста, обеспечьте своевременное завершение этого платежа, чтобы избежать каких-либо неудобств.</p><p> Благодарим за сотрудничество.</p>', 0, '2026-07-30 12:06:45', '2026-07-30 12:06:45'),
(187, 12, 'pt', 'Payment Reminder', '<p>Prezado {customer_name},<br /></p><p> Este é um lembrete amigável sobre o pagamento parcial. </p><p> Recebemos o pagamento inicial de {amount} em {date} prontamente, pelo qual agradecemos.</p><p><br>O saldo restante de {remaining_amount} vence em {remaining_date} data.</p><p> Garanta a conclusão atempada deste pagamento para evitar qualquer inconveniente.</p><p> Obrigado pela sua cooperação.</p>', 0, '2026-07-30 12:06:45', '2026-07-30 12:06:45'),
(188, 12, 'zh', 'Payment Reminder', '<p>尊敬的{customer_name}，<br /></p><p>这是关于部分付款的友好提醒。 </p><p> 我们已于 {date} 立即收到 {amount} 的首期付款，对此我们表示感谢。</p><p><br>剩余的 {remaining_amount} 余额应于 {remaining_date}日期。</p><p>请确保及时完成此付款，以免造成任何不便。</p><p>感谢您的合作。</p>', 0, '2026-07-30 12:06:45', '2026-07-30 12:06:45'),
(189, 12, 'he', 'Payment Reminder', '<p>{customer_name} היקר,<br /></p><p> זוהי תזכורת ידידותית לגבי התשלום החלקי. </p><p> קיבלנו את התשלום הראשוני בסך {amount} בתאריך {date} באופן מיידי, ועל כך אנו מודים לך.</p><p><br>היתרה הנותרת בסך {remaining_amount} תגיע ב-{remaining_date}.</p><p> אנא הקפד להשלים בזמן של תשלום זה כדי למנוע אי נוחות.</p><p> תודה על שיתוף הפעולה.</p>', 0, '2026-07-30 12:06:45', '2026-07-30 12:06:45'),
(190, 12, 'tr', 'Payment Reminder', '<p>Sayın {customer_name},<br /></p><p> Bu, kısmi ödemeyle ilgili dostça bir hatırlatmadır. </p><p> {amount} tutarındaki ilk ödemeyi {date} tarihinde derhal aldık, bunun için size teşekkür ederiz.</p><p><br>Kalan {remaining_amount} bakiyesinin vadesi {remaining_date} tarihi.</p><p> Herhangi bir rahatsızlığı önlemek için lütfen bu ödemenin zamanında tamamlandığından emin olun.</p><p> İşbirliğiniz için teşekkür ederiz.</p>', 0, '2026-07-30 12:06:45', '2026-07-30 12:06:45'),
(191, 12, 'pt-br', 'Payment Reminder', '<p>Prezado {customer_name},<br /></p><p> Este é um lembrete amigável sobre o pagamento parcial. </p><p> Recebemos o pagamento inicial de {amount} em {date} prontamente, pelo qual agradecemos.</p><p><br>O saldo restante de {remaining_amount} vence em {remaining_date} data.</p><p> Garanta a conclusão atempada deste pagamento para evitar qualquer inconveniente.</p><p> Obrigado pela sua cooperação.</p>', 0, '2026-07-30 12:06:45', '2026-07-30 12:06:45'),
(192, 13, 'ar', 'Payment Reminder', '<p>عزيزي {customer_name}،<br /></p><p> هذا تذكير ودي بشأن الدفع الجزئي. </p><p> لقد استلمنا الدفعة الأولية بقيمة {amount} في {date} على الفور، ونحن نشكرك على ذلك.</p><p><br>يستحق الرصيد المتبقي بقيمة {remaining_amount} في {remaining_date} date.</p><p> يرجى التأكد من إتمام هذه الدفعة في الوقت المناسب لتجنب أي إزعاج.</p><p> شكرًا لك على تعاونك.</p>', 0, '2026-08-17 11:29:41', '2026-08-17 11:29:41'),
