INSERT INTO `marketplace_page_settings` (`id`, `name`, `value`, `module`, `created_at`, `updated_at`) VALUES
(1, 'product_main_banner', '', 'AdditionalCustomFields', '2026-06-10 16:06:45', '2026-06-10 16:06:45'),
(2, 'product_main_status', 'on', 'AdditionalCustomFields', '2026-06-10 16:06:45', '2026-06-10 16:06:45'),
(3, 'product_main_heading', 'AdditionalCustomFields', 'AdditionalCustomFields', '2026-06-10 16:06:45', '2026-06-10 16:06:45'),
(4, 'product_main_description', '<p>The Additional Custom Field module in eCommerceGo SAAS empowers businesses to enrich their products with customized fields, enabling them to gather precise and relevant information. This module is particularly beneficial for industries such as spas, clinics, or other appointment-based services where capturing detailed client information is essential. By leveraging this feature, admins can create tailored data fields that enhance the overall product configuration and booking experience, ensuring that the collected information aligns with their specific business needs.</p>', 'AdditionalCustomFields', '2026-06-10 16:06:45', '2026-06-10 16:06:45'),
(5, 'product_main_demo_link', '#', 'AdditionalCustomFields', '2026-06-10 16:06:45', '2026-06-10 16:06:45'),
(6, 'product_main_demo_button_text', 'View Live Demo', 'AdditionalCustomFields', '2026-06-10 16:06:45', '2026-06-10 16:06:45'),
(7, 'dedicated_theme_heading', 'Enabling the Additional Custom Field Feature.', 'AdditionalCustomFields', '2026-06-10 16:06:45', '2026-06-10 16:06:45'),
(8, 'dedicated_theme_description', '<p>Before utilizing the Additional Custom Field module, administrators must enable its functionality within the eCommerceGo SAAS settings. This critical step unlocks the modules tools, allowing admins to define and add custom fields. Activation is simple: navigate to the settings menu, locate the Additional Custom Field toggle, and switch it on. Once enabled, admins can customize fields for each product, paving the way for more detailed information capture during product creation and configuration.</p>', 'AdditionalCustomFields', '2026-06-10 16:06:45', '2026-06-10 16:06:45'),
(9, 'dedicated_theme_sections', '[\n            {\n              \"dedicated_theme_section_image\": \"\",\n              \"dedicated_theme_section_heading\": \"Adding Custom Fields for Products\",\n              \"dedicated_theme_section_description\": \"With the feature activated, administrators can introduce custom fields while creating or editing a product. These fields allow for capturing specific data that might be unique to a businesss operation, such as client preferences, additional instructions, or service-specific details. Custom fields can include text inputs, dropdown menus, or checkboxes, offering flexibility in data collection. Once defined during product creation, these fields become an integral part of the product details and ensure that all necessary information is gathered upfront.\"\n            },\n            {\n              \"dedicated_theme_section_image\": \"\",\n              \"dedicated_theme_section_heading\": \"Enhancing Product Details with Custom Fields\",\n              \"dedicated_theme_section_description\": \"The Additional Custom Field module is designed to optimize the administrative process of product configuration. By allowing admins to input additional field values during product creation, the module ensures that relevant details are automatically included in the Additional Custom Field page. This centralized repository of information reduces manual data entry and ensures consistency across records. The enhanced product details streamline internal workflows and improve communication between admins and their customers.\"\n            },\n            {\n              \"dedicated_theme_section_image\": \"\",\n              \"dedicated_theme_section_heading\": \"Benefits of Streamlined Data Collection\",\n              \"dedicated_theme_section_description\": \"The Additional Custom Field module simplifies data collection, reducing errors and the need for follow-up inquiries. By embedding custom fields directly into product creation, businesses can ensure that critical information is captured early in the process. This feature supports a smoother, more efficient workflow, enabling better customer service and operational excellence. In turn, businesses can deliver personalized experiences that enhance customer satisfaction and foster loyalty, making this module a valuable addition to any eCommerceGo SAAS implementation.\"\n            }\n          ]\n          ', 'AdditionalCustomFields', '2026-06-10 16:06:45', '2026-06-10 16:06:45'),
(10, 'dedicated_theme_sections_heading', '', 'AdditionalCustomFields', '2026-06-10 16:06:45', '2026-06-10 16:06:45'),
(11, 'screenshots', '[{\"screenshots\":\"\",\"screenshots_heading\":\"AdditionalCustomFields\"},{\"screenshots\":\"\",\"screenshots_heading\":\"AdditionalCustomFields\"},{\"screenshots\":\"\",\"screenshots_heading\":\"AdditionalCustomFields\"},{\"screenshots\":\"\",\"screenshots_heading\":\"AdditionalCustomFields\"},{\"screenshots\":\"\",\"screenshots_heading\":\"AdditionalCustomFields\"}]', 'AdditionalCustomFields', '2026-06-10 16:06:45', '2026-06-10 16:06:45'),
(12, 'addon_heading', 'Why choose dedicated modules for Your Business?', 'AdditionalCustomFields', '2026-06-10 16:06:45', '2026-06-10 16:06:45'),
(13, 'addon_description', '<p>With EcommerceGo, you can conveniently manage all your business functions from a single location.</p>', 'AdditionalCustomFields', '2026-06-10 16:06:45', '2026-06-10 16:06:45'),
