(54, 'dedicated_theme_description', '<p>Effortlessly integrate and extend your ecommerce capabilities with EcommerceGo robust and scalable API module.</p>', 'Api', '2026-06-10 16:08:46', '2026-06-10 16:08:46'),
(55, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Real-Time Data Synchronization\",\"dedicated_theme_section_description\":\"With the eCommerceGo API, you can ensure real-time synchronization of data across all your platforms. Whether its updating product inventories, tracking orders, or managing customer information, our API facilitates instant data exchange, keeping everything up-to-date and accurate, which is critical for effective decision-making and customer satisfaction.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Extensive Documentation and Support\",\"dedicated_theme_section_description\":\"The eCommerceGo API comes with comprehensive documentation and robust support to assist developers at every step. Our detailed guides, code samples, and responsive support team make it easy to implement and troubleshoot integrations, ensuring you can leverage the full potential of our API with minimal hassle.\"}]', 'Api', '2026-06-10 16:08:46', '2026-06-10 16:08:46'),
