(141, 'product_main_heading', 'Boost Sales', 'BoostSales', '2026-06-10 16:11:49', '2026-06-10 16:11:49'),
(142, 'product_main_description', '<p>Imagine watching your sales soar without lifting a finger. The eCommerceGo Boost Sales module makes it a reality. This powerful tool automates your marketing efforts and equips you with features to personalize customer experiences, recover abandoned carts, and optimize campaigns for maximum impact.</p>', 'BoostSales', '2026-06-10 16:11:49', '2026-06-10 16:11:49'),
(143, 'product_main_demo_link', '#', 'BoostSales', '2026-06-10 16:11:49', '2026-06-10 16:11:49'),
