(145, 'dedicated_theme_heading', 'Effortless Marketing Automation', 'BoostSales', '2026-06-10 16:11:49', '2026-06-10 16:11:49'),
(146, 'dedicated_theme_description', '<p>Supercharge your online sales with eCommerceGos Boost Sales module – your ultimate tool for driving conversions and increasing revenue effortlessly!</p>', 'BoostSales', '2026-06-10 16:11:49', '2026-06-10 16:11:49'),
(147, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Never Lose a Sale Again\",\"dedicated_theme_section_description\":\"Abandoned carts are a thing of the past. Automated campaigns recapture lost sales by reminding customers about forgotten items and enticing them to complete their purchase with irresistible incentives. Go beyond generic marketing blasts. Segment your audience based on their unique preferences and top purchases that resonate with each customer, increasing engagement and driving conversions.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Unleash Your Sales Potential with eCommerceGo Boost Sales Module\",\"dedicated_theme_section_description\":\"Boost Sales module showcases top seller products or selected products, allowing customers to easily add all products to their cart with a single click. Admins can effortlessly choose which products to highlight, ensuring the best items are always front and center for your customers.\"}]', 'BoostSales', '2026-06-10 16:11:49', '2026-06-10 16:11:49'),
(148, 'dedicated_theme_sections_heading', '', 'BoostSales', '2026-06-10 16:11:49', '2026-06-10 16:11:49'),
