(164, 'product_main_heading', 'BulkDelete', 'BulkDelete', '2026-06-10 16:11:49', '2026-06-10 16:11:49'),
(165, 'product_main_description', '<p>The Bulk Delete Module is designed to streamline the process of managing your inventory by allowing you to remove multiple items at once. This feature is ideal for businesses that regularly need to update or clean up their product listings, saving time and reducing manual effort. With just a few clicks, you can clear out outdated, discontinued, or irrelevant products from your stores catalog.</p>', 'BulkDelete', '2026-06-10 16:11:49', '2026-06-10 16:11:49'),
(166, 'product_main_demo_link', '#', 'BulkDelete', '2026-06-10 16:11:49', '2026-06-10 16:11:49'),
(167, 'product_main_demo_button_text', 'View Live Demo', 'BulkDelete', '2026-06-10 16:11:49', '2026-06-10 16:11:49'),
(168, 'dedicated_theme_heading', 'User-Friendly and Efficient', 'BulkDelete', '2026-06-10 16:11:49', '2026-06-10 16:11:49'),
(169, 'dedicated_theme_description', '<p>Using this module is straightforward and user-friendly, ensuring that even those with limited technical expertise can efficiently manage their inventory. The intuitive interface guides you through selecting the products you want to delete, whether it\'s a specific category, a collection of discontinued items, or products that haven\'t been performing well.</p>', 'BulkDelete', '2026-06-10 16:11:49', '2026-06-10 16:11:49'),
(170, 'dedicated_theme_sections', '[\n            {\n                \"dedicated_theme_section_image\": \"\",\n                \"dedicated_theme_section_heading\": \"Fast and Accurate Deletions\",\n                \"dedicated_theme_section_description\": \"Once products are selected, the Bulk Delete Module quickly processes the request, making changes in real-time. This feature is particularly beneficial for large eCommerce stores with extensive inventories, where manually deleting items can be time-consuming and error-prone. The speed and accuracy of bulk deletion ensure that your store is always up to date with minimal effort.\"\n            },\n            {\n                \"dedicated_theme_section_image\": \"\",\n                \"dedicated_theme_section_heading\": \"Flexible Deletion Options\",\n                \"dedicated_theme_section_description\": \"One of the key advantages of this module is its flexibility. You can choose to delete products based on various filters, such as categories, tags, or custom attributes, giving you precise control over which items are removed. This helps prevent accidental deletions while offering a comprehensive solution for managing your product catalog efficiently.\"\n            },\n            {\n                \"dedicated_theme_section_image\": \"\",\n                \"dedicated_theme_section_heading\": \"Maintain a Clean and Organized Store\",\n                \"dedicated_theme_section_description\": \"The Bulk Delete Module not only improves workflow but also helps maintain a clutter-free, professional store layout. By regularly removing products that no longer align with your brand or sales goals, you keep your store clean and organized, enhancing the overall customer experience.\"\n            }\n        ]', 'BulkDelete', '2026-06-10 16:11:49', '2026-06-10 16:11:49'),
(171, 'dedicated_theme_sections_heading', '', 'BulkDelete', '2026-06-10 16:11:49', '2026-06-10 16:11:49'),
