(185, 'product_main_banner', '', 'BundleProduct', '2026-06-10 16:11:50', '2026-06-10 16:11:50'),
(186, 'product_main_status', 'on', 'BundleProduct', '2026-06-10 16:11:50', '2026-06-10 16:11:50'),
(187, 'product_main_heading', 'BundleProduct', 'BundleProduct', '2026-06-10 16:11:50', '2026-06-10 16:11:50'),
(188, 'product_main_description', '<p>Gone are the days of tedious, time-consuming shopping experiences. With Bundle Products, we redefine convenience by bringing together all your essential items into one comprehensive package. Whether you are looking to revamp your wardrobe, upgrade your skincare routine, or stock up on household essentials, our bundles offer everything you need in one convenient click. Say goodbye to endless scrolling and hello to streamlined shopping experiences.</p>', 'BundleProduct', '2026-06-10 16:11:50', '2026-06-10 16:11:50'),
