(191, 'dedicated_theme_heading', 'Maximize Savings, Minimize Hassle', 'BundleProduct', '2026-06-10 16:11:50', '2026-06-10 16:11:50');
INSERT INTO `marketplace_page_settings` (`id`, `name`, `value`, `module`, `created_at`, `updated_at`) VALUES
(192, 'dedicated_theme_description', '<p>Saving money has never been easier with our Bundle Product module. By bundling products together, we unlock exclusive discounts and promotions that allow you to maximize your savings with every purchase. Why pay full price for individual items when you can enjoy significant discounts by bundling? Say goodbye to buyer is remorse and hello to smart, savvy shopping.</p>', 'BundleProduct', '2026-06-10 16:11:50', '2026-06-10 16:11:50'),
(193, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Tailored to Perfection\",\"dedicated_theme_section_description\":\"We understand that every shopper has unique preferences and needs. That is why our Bundle Product module empowers you to customize your bundles to perfection. Mix and match your favorite products, choose your preferred sizes and colors, and create a bundle that is tailor-made just for you. Whether you are curating the perfect gift set or treating yourself to a well-deserved indulgence, our customizable options ensure that you get exactly what you want, every time.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Discover Endless Possibilities\",\"dedicated_theme_section_description\":\"With Bundle Products, shopping becomes an adventure filled with endless possibilities. Each bundle presents an opportunity to explore new products, discover hidden gems, and indulge in exciting surprises. From deluxe beauty sets to curated culinary collections, our bundles offer a curated selection of products that are sure to delight and inspire. Who knows? You might just stumble upon your new favorite product with every bundle purchase.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Embrace Sustainable Shopping Practices\",\"dedicated_theme_section_description\":\"<p>At eCommerceGo SaaS, we are committed to sustainability and environmental stewardship. That is why our Bundle Product module not only offers convenience and savings but also promotes sustainable shopping practices. By bundling products together, we minimize packaging waste and reduce our carbon footprint, contributing to a greener, more eco-friendly future. With each bundle purchase, you are not just saving money—you are also making a positive impact on the planet.<\\/p>\"}]', 'BundleProduct', '2026-06-10 16:11:50', '2026-06-10 16:11:50'),
(194, 'dedicated_theme_sections_heading', '', 'BundleProduct', '2026-06-10 16:11:50', '2026-06-10 16:11:50'),
