(279, 'product_main_heading', 'Coupon Email', 'CouponEmail', '2026-06-10 16:18:23', '2026-06-10 16:18:23'),
(280, 'product_main_description', '<p>Enhance your marketing strategy and boost customer engagement with the Email Coupon module of eCommerceGo SaaS. This feature empowers you to send targeted email coupons to your customers based on specific triggers, ensuring timely and personalized communication that drives conversions and increases loyalty.</p>', 'CouponEmail', '2026-06-10 16:18:23', '2026-06-10 16:18:23'),
(281, 'product_main_demo_link', '#', 'CouponEmail', '2026-06-10 16:18:23', '2026-06-10 16:18:23'),
(282, 'product_main_demo_button_text', 'View Live Demo', 'CouponEmail', '2026-06-10 16:18:23', '2026-06-10 16:18:23'),
(283, 'dedicated_theme_heading', 'Tailored Offers for Every Customer Journey', 'CouponEmail', '2026-06-10 16:18:23', '2026-06-10 16:18:23'),
(284, 'dedicated_theme_description', '<p>With eCommerceGo SaaS, you have the flexibility to choose from three options to trigger email coupon delivery: user registration, first purchase, or specific order threshold. This allows you to tailor your offers to different stages of the customer journey, maximizing relevance and effectiveness. Whether you want to incentivize new sign-ups, reward first-time buyers, or encourage repeat purchases, our module has you covered.</p>', 'CouponEmail', '2026-06-10 16:18:23', '2026-06-10 16:18:23'),
(285, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Seamless Integration and Automation\",\"dedicated_theme_section_description\":\"Gone are the days of manually sending out coupons to your customers. With eCommerceGo SaaS, the Email Coupon module automates the process, saving you time and effort. Simply set your triggers and coupon parameters, and let our platform handle the rest. Whether you`re managing a small business or a large enterprise, our seamless integration ensures that your email campaigns run smoothly and efficiently.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Increase Conversions and Customer Retention\",\"dedicated_theme_section_description\":\"By delivering targeted coupons directly to your customers` inboxes, you can significantly increase conversion rates and drive repeat business. Studies show that personalized offers are more likely to be redeemed, leading to higher customer satisfaction and loyalty. With eCommerceGo SaaS, you can nurture customer relationships and keep them coming back for more with irresistible deals and discounts.\"}]', 'CouponEmail', '2026-06-10 16:18:23', '2026-06-10 16:18:23'),
(286, 'dedicated_theme_sections_heading', '', 'CouponEmail', '2026-06-10 16:18:23', '2026-06-10 16:18:23'),
