(300, 'product_main_banner', '', 'CouponList', '2026-06-10 16:20:15', '2026-06-10 16:20:15'),
(301, 'product_main_status', 'on', 'CouponList', '2026-06-10 16:20:15', '2026-06-10 16:20:15'),
(302, 'product_main_heading', 'Coupon List', 'CouponList', '2026-06-10 16:20:15', '2026-06-10 16:20:15'),
(303, 'product_main_description', '<p>Our Coupon List Module simplifies the process of managing discounts for your online store. With clear and organized listings, you can effortlessly keep track of all active promotions, their respective discount amounts, and expiration dates. This streamlines your marketing efforts, ensuring that you can easily monitor and update your discount strategy to maximize savings for both your customers and your business.</p>', 'CouponList', '2026-06-10 16:20:15', '2026-06-10 16:20:15'),
(304, 'product_main_demo_link', '#', 'CouponList', '2026-06-10 16:20:15', '2026-06-10 16:20:15'),
(305, 'product_main_demo_button_text', 'View Live Demo', 'CouponList', '2026-06-10 16:20:15', '2026-06-10 16:20:15'),
(306, 'dedicated_theme_heading', 'Strategic Promotion Planning', 'CouponList', '2026-06-10 16:20:15', '2026-06-10 16:20:15'),
(307, 'dedicated_theme_description', '<p>The Coupon List Module empowers you to strategically plan your promotional campaigns. By knowing the validity periods of each coupon, you can schedule promotions to coincide with peak shopping times or align them with specific marketing initiatives.</p>', 'CouponList', '2026-06-10 16:20:15', '2026-06-10 16:20:15'),
(308, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Boosted Sales and Conversion Rates\",\"dedicated_theme_section_description\":\"Coupons are powerful tools for driving sales and increasing conversion rates. With enticing discounts readily available through our Coupon List Module, you can attract more customers and encourage them to complete their purchases. Whether its a percentage off the total order price or a fixed amount discount, these offers incentivize shoppers to buy, resulting in boosted sales and revenue for your eCommerce business.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Flexibility and Customization\",\"dedicated_theme_section_description\":\"Our Coupon List Module offers flexibility and customization options to suit your unique business needs. You can easily create, edit, and deactivate coupons as needed, allowing you to adapt your discount strategy in response to changing market conditions or promotional goals. This flexibility enables you to stay agile in your marketing efforts and continually optimize your discount offerings for maximum effectiveness.\"}]', 'CouponList', '2026-06-10 16:20:15', '2026-06-10 16:20:15'),
(309, 'dedicated_theme_sections_heading', '', 'CouponList', '2026-06-10 16:20:15', '2026-06-10 16:20:15'),
