(346, 'product_main_banner', '', 'Donation', '2026-06-10 16:21:03', '2026-06-10 16:21:03'),
(347, 'product_main_status', 'on', 'Donation', '2026-06-10 16:21:03', '2026-06-10 16:21:03'),
(348, 'product_main_heading', 'Donation', 'Donation', '2026-06-10 16:21:03', '2026-06-10 16:21:03'),
(349, 'product_main_description', '<p>The Donation Module of eCommerceGo SaaS empowers businesses to make a positive difference by integrating charitable giving into their online platforms. This module enables businesses to align their brand values with social responsibility initiatives, fostering goodwill and making a meaningful impact on causes that matter. By providing customers with the option to donate during the checkout process, businesses can leverage their e-commerce presence to support charitable organizations and contribute to positive social change.</p>', 'Donation', '2026-06-10 16:21:03', '2026-06-10 16:21:03'),
(350, 'product_main_demo_link', '#', 'Donation', '2026-06-10 16:21:03', '2026-06-10 16:21:03'),
(351, 'product_main_demo_button_text', 'View Live Demo', 'Donation', '2026-06-10 16:21:03', '2026-06-10 16:21:03'),
(352, 'dedicated_theme_heading', 'Foster Social Impact Through Online Giving', 'Donation', '2026-06-10 16:21:03', '2026-06-10 16:21:03'),
(353, 'dedicated_theme_description', '<p>The Donation module of eCommerceGo SaaS empowers businesses to seamlessly integrate charitable giving into their online platforms, fostering goodwill and social impact with ease.</p>', 'Donation', '2026-06-10 16:21:03', '2026-06-10 16:21:03'),
(354, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Seamless Integration for Giving Back\",\"dedicated_theme_section_description\":\"With the Donation Module, businesses can seamlessly integrate donation options into their checkout flow, providing customers with an effortless way to give back. By incorporating donation prompts at strategic points during the purchasing journey, businesses can raise awareness about important causes and inspire customers to contribute. This frictionless approach to online giving enhances the overall customer experience and demonstrates a commitment to corporate social responsibility.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Amplify Brand Reputation and Trust\",\"dedicated_theme_section_description\":\"Supporting charitable causes through the Donation Module not only benefits those in need but also enhances a business brand reputation and trustworthiness. Customers are increasingly drawn to socially conscious brands that prioritize giving back to the community. By showcasing their commitment to philanthropy, businesses can differentiate themselves from competitors and build stronger connections with their audience, fostering loyalty and positive brand associations.\"}]', 'Donation', '2026-06-10 16:21:03', '2026-06-10 16:21:03'),
(355, 'dedicated_theme_sections_heading', '', 'Donation', '2026-06-10 16:21:03', '2026-06-10 16:21:03'),
