INSERT INTO `marketplace_page_settings` (`id`, `name`, `value`, `module`, `created_at`, `updated_at`) VALUES
(391, 'dedicated_theme_section_status', 'on', 'Duo2FA', '2026-06-10 16:21:55', '2026-06-10 16:21:55'),
(392, 'product_main_banner', '', 'EMailBox', '2026-06-10 16:22:51', '2026-06-10 16:22:51'),
(393, 'product_main_status', 'on', 'EMailBox', '2026-06-10 16:22:51', '2026-06-10 16:22:51'),
(394, 'product_main_heading', 'EMail Box', 'EMailBox', '2026-06-10 16:22:51', '2026-06-10 16:22:51'),
(395, 'product_main_description', '<p>EMail Box module is a powerful tool designed to streamline your email management process. It seamlessly integrates with your SMTP server, giving you unprecedented control over your email account\'s various folders, including Inbox, Drafts, Spam, Sent, Trash, and Archive. But that\'s not all; it also empowers you to interact with your emails in ways that were previously unimaginable.</p>', 'EMailBox', '2026-06-10 16:22:51', '2026-06-10 16:22:51'),
(396, 'product_main_demo_link', '#', 'EMailBox', '2026-06-10 16:22:51', '2026-06-10 16:22:51'),
(397, 'product_main_demo_button_text', 'View Live Demo', 'EMailBox', '2026-06-10 16:22:51', '2026-06-10 16:22:51'),
(398, 'dedicated_theme_heading', '<h2><b>Take Your Email </b> Experience to the Next Level with EMail Box</h2>', 'EMailBox', '2026-06-10 16:22:51', '2026-06-10 16:22:51'),
(399, 'dedicated_theme_description', '<p>Are you tired of the same old email routine? It\'s time to take your email experience to the next level with EMail Box! Our innovative module is designed to elevate your email management, making it easier and more efficient than ever before.</p>', 'EMailBox', '2026-06-10 16:22:51', '2026-06-10 16:22:51'),
(400, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Effortlessly Manage Your Email with EMail Box\",\"dedicated_theme_section_description\":\"<p>In the EMail Box module, you gain seamless access to your email folders, including Inbox, Drafts, Spam, Sent, Trash, and Archive, all hosted on your SMTP server. This powerful tool empowers users to not only retrieve emails but also interact with them in real-time.<\\/p>\",\"dedicated_theme_section_cards\":{\"1\":{\"title\":null,\"description\":null}}},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"EMail Box: Seamlessly Sync Your Email Actions\",\"dedicated_theme_section_description\":\"<p>With EMail Box, every action you take—be it starring, marking as unread, or moving emails to different folders—syncs in real-time with your SMTP server email box. Experience unparalleled control and convenience as your email management becomes effortless and perfectly harmonized with your SMTP account.<\\/p>\",\"dedicated_theme_section_cards\":{\"1\":{\"title\":null,\"description\":null}}}]', 'EMailBox', '2026-06-10 16:22:51', '2026-06-10 16:22:51'),
(401, 'dedicated_theme_sections_heading', '', 'EMailBox', '2026-06-10 16:22:51', '2026-06-10 16:22:51'),
(402, 'screenshots', '[{\"screenshots\":\"\",\"screenshots_heading\":\"EMail Box\"},{\"screenshots\":\"\",\"screenshots_heading\":\"EMail Box\"},{\"screenshots\":\"\",\"screenshots_heading\":\"EMail Box\"},{\"screenshots\":\"\",\"screenshots_heading\":\"EMail Box\"},{\"screenshots\":\"\",\"screenshots_heading\":\"EMail Box\"}]', 'EMailBox', '2026-06-10 16:22:51', '2026-06-10 16:22:51'),
(403, 'addon_heading', '<h2>Why choose dedicated modules<b> for Your Business?</b></h2>', 'EMailBox', '2026-06-10 16:22:51', '2026-06-10 16:22:51'),
(404, 'addon_description', '<p>With eCommerceGo, you can conveniently manage all your business functions from a single location.</p>', 'EMailBox', '2026-06-10 16:22:51', '2026-06-10 16:22:51'),
