(417, 'product_main_heading', 'Free Shipping Pop-Up', 'FreeShippingPopup', '2026-06-10 16:24:48', '2026-06-10 16:24:48'),
(418, 'product_main_description', '<p>EcommerceGo SaaS is proud to introduce our new Free Shipping Pop-Up Module, a powerful tool designed to enhance the shopping experience for your customers while boosting your sales. This innovative feature automatically displays a pop-up notification offering free shipping to eligible customers, encouraging them to complete their purchases. With this module, you can effortlessly highlight one of the most attractive incentives for online shoppers, helping to reduce cart abandonment and increase conversion rates.</p>', 'FreeShippingPopup', '2026-06-10 16:24:48', '2026-06-10 16:24:48'),
(419, 'product_main_demo_link', '#', 'FreeShippingPopup', '2026-06-10 16:24:48', '2026-06-10 16:24:48'),
(420, 'product_main_demo_button_text', 'View Live Demo', 'FreeShippingPopup', '2026-06-10 16:24:48', '2026-06-10 16:24:48'),
(421, 'dedicated_theme_heading', 'Enhance Customer Experience', 'FreeShippingPopup', '2026-06-10 16:24:48', '2026-06-10 16:24:48'),
(422, 'dedicated_theme_description', '<p>Free shipping is a powerful motivator for online shoppers, and our pop-up module ensures that this incentive is prominently displayed to your customers at the right moment.</p>', 'FreeShippingPopup', '2026-06-10 16:24:48', '2026-06-10 16:24:48'),
(423, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Seamless Integration and Customization\",\"dedicated_theme_section_description\":\"Integrating the Free Shipping Pop-Up Module into your EcommerceGo platform is a breeze. The module is designed to work seamlessly with your existing setup, requiring minimal configuration. You can easily customize the appearance and messaging of the pop-up to align with your brands look and feel. Tailor the criteria for free shipping eligibility, such as minimum order value or specific product categories, to meet your business needs. This flexibility ensures that your free shipping offer is both appealing to customers and beneficial for your bottom line.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Boost Sales and Reduce Cart Abandonment\",\"dedicated_theme_section_description\":\"Cart abandonment is a common challenge for online retailers, often caused by unexpected shipping costs. The Free Shipping Pop-Up Module addresses this issue head-on by highlighting the availability of free shipping early in the shopping process. When customers know they can save on shipping costs, they are more likely to proceed to checkout. By reducing one of the main barriers to purchase, this module helps you capture more sales and decrease the number of abandoned carts on your site.\"}]', 'FreeShippingPopup', '2026-06-10 16:24:48', '2026-06-10 16:24:48'),
(424, 'dedicated_theme_sections_heading', '', 'FreeShippingPopup', '2026-06-10 16:24:48', '2026-06-10 16:24:48'),
