(440, 'product_main_heading', 'Google Authentication', 'GoogleAuthentication', '2026-06-10 16:24:49', '2026-06-10 16:24:49'),
(441, 'product_main_description', '<p>Integrate Google Authentication with eCommerceGo to streamline user access and enhance security. By leveraging Google’s robust authentication system, you make it easier for users to sign in with their existing Google accounts, reducing the need for additional passwords and usernames. This simplifies the login process and minimizes potential barriers for new users.</p>', 'GoogleAuthentication', '2026-06-10 16:24:49', '2026-06-10 16:24:49'),
(442, 'product_main_demo_link', '#', 'GoogleAuthentication', '2026-06-10 16:24:49', '2026-06-10 16:24:49'),
(443, 'product_main_demo_button_text', 'View Live Demo', 'GoogleAuthentication', '2026-06-10 16:24:49', '2026-06-10 16:24:49'),
(444, 'dedicated_theme_heading', 'Stay Up-to-Date', 'GoogleAuthentication', '2026-06-10 16:24:49', '2026-06-10 16:24:49'),
(445, 'dedicated_theme_description', '<p>By using Google Authentication, you benefit from ongoing updates and improvements made by Google’s security team. This ensures that your authentication system stays current with the latest security protocols and features. Regular updates and enhancements provide peace of mind that your platform remains secure and efficient as new security challenges emerge.</p>', 'GoogleAuthentication', '2026-06-10 16:24:49', '2026-06-10 16:24:49'),
(446, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Streamline Management\",\"dedicated_theme_section_description\":\"Integrating Google Authentication into your eCommerceGo platform simplifies user management for administrators. You can easily manage and monitor user access without the complexity of handling separate authentication systems. This integration helps in maintaining a clean and organized user database, facilitating smoother operations and better user support.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Enhance Security\",\"dedicated_theme_section_description\":\"Google Authentication brings advanced security features to your eCommerceGo platform. With features like two-factor authentication and secure token management, you ensure that user accounts are protected against unauthorized access. This added security layer helps safeguard sensitive information and boost overall user confidence in your platform.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Improve User Experience\",\"dedicated_theme_section_description\":\"Providing a seamless login experience is crucial for user satisfaction. Google Authentication allows users to quickly and effortlessly access their accounts without remembering multiple passwords. This ease of use can lead to increased user engagement and lower bounce rates, as users are less likely to experience frustration with the sign-in process.\"}]', 'GoogleAuthentication', '2026-06-10 16:24:49', '2026-06-10 16:24:49'),
(447, 'dedicated_theme_sections_heading', '', 'GoogleAuthentication', '2026-06-10 16:24:49', '2026-06-10 16:24:49'),
