(509, 'product_main_heading', 'Helpdesk', 'Helpdesk', '2026-06-10 16:30:35', '2026-06-10 16:30:35'),
(510, 'product_main_description', '<p>Welcome to our Helpdesk Module, a robust solution designed to facilitate seamless communication between businesses and super admins. Easily manage customer inquiries, bug reports, and product-related issues through our intuitive interface, complete with attachment support for comprehensive ticket handling. Engage in real-time chat for instant issue resolution and efficient collaboration, ensuring a superior customer service experience.</p>', 'Helpdesk', '2026-06-10 16:30:35', '2026-06-10 16:30:35'),
