(530, 'product_main_banner', '', 'HubSpot', '2026-06-10 16:32:30', '2026-06-10 16:32:30'),
(531, 'product_main_status', 'on', 'HubSpot', '2026-06-10 16:32:30', '2026-06-10 16:32:30'),
(532, 'product_main_heading', 'HubSpot', 'HubSpot', '2026-06-10 16:32:30', '2026-06-10 16:32:30'),
(533, 'product_main_description', '<p>HubSpot is an integrated customer platform that empowers scaling businesses to provide exceptional customer experiences. It offers a cohesive solution, combining powerful tools that work seamlessly together. With HubSpot, the focus is on prioritizing customers, ensuring easy customization, and fostering team collaboration through its Smart CRM. Ultimately, HubSpot helps businesses create delightful customer interactions.</p>', 'HubSpot', '2026-06-10 16:32:31', '2026-06-10 16:32:31'),
(534, 'product_main_demo_link', '#', 'HubSpot', '2026-06-10 16:32:31', '2026-06-10 16:32:31'),
(535, 'product_main_demo_button_text', 'View Live Demo', 'HubSpot', '2026-06-10 16:32:31', '2026-06-10 16:32:31'),
(536, 'dedicated_theme_heading', 'Effortless Data Synchronization with HubSpot CRM', 'HubSpot', '2026-06-10 16:32:31', '2026-06-10 16:32:31'),
(537, 'dedicated_theme_description', '<p>Streamline your sales process with HubSpot CRM\'s seamless data synchronization feature. Keep your HubSpot data up-to-date and in sync, ensuring accurate and real-time information across your sales team. Boost efficiency, improve collaboration, and close data faster with this powerful functionality.</p>', 'HubSpot', '2026-06-10 16:32:31', '2026-06-10 16:32:31'),
(538, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Benefits of Using HubSpot CRM for Managing Data\",\"dedicated_theme_section_description\":\"<p>HubSpot CRM streamlines data management with features like data tracking, sales automation, and pipeline visibility. It offers real-time updates on data progress, simplifies communication with prospects, and enhances sales team productivity. Plus, its integration with other HubSpot tools ensures a comprehensive approach to managing sales data, leading to improved conversions and revenue growth.</p>\",\"dedicated_theme_section_cards\":{\"1\":{\"title\":null,\"description\":null}}},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"How Does It Work?\",\"dedicated_theme_section_description\":\"<p>Ever wondered how to effortlessly integrate your HubSpot CRM data with website? Our module simplifies the process by syncing data directly from HubSpot CRM to your website . Easily add and manage your data, streamlining your workflow and boosting productivity. Discover the power of seamless data synchronization today.</p>\",\"dedicated_theme_section_cards\":{\"1\":{\"title\":null,\"description\":null}}},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Enhance Marketing Efforts with HubSpot\'s All-in-One Solution\",\"dedicated_theme_section_description\":\"<p>HubSpot\'s integrated platform goes beyond CRM, empowering businesses with a suite of marketing tools designed to drive growth. From creating engaging email campaigns to managing social media interactions and tracking performance analytics, HubSpot offers everything needed to execute effective marketing strategies. Its intuitive interface and automation capabilities ensure that businesses can reach the right audience at the right time, fostering stronger connections and boosting brand loyalty. </p>\",\"dedicated_theme_section_cards\":{\"1\":{\"title\":null,\"description\":null}}}]', 'HubSpot', '2026-06-10 16:32:31', '2026-06-10 16:32:31'),
(539, 'dedicated_theme_sections_heading', '', 'HubSpot', '2026-06-10 16:32:31', '2026-06-10 16:32:31'),
