(553, 'product_main_banner', '', 'ImportExport', '2026-06-10 16:33:48', '2026-06-10 16:33:48'),
(554, 'product_main_status', 'on', 'ImportExport', '2026-06-10 16:33:48', '2026-06-10 16:33:48'),
(555, 'product_main_heading', 'ImportExport', 'ImportExport', '2026-06-10 16:33:48', '2026-06-10 16:33:48'),
(556, 'product_main_description', '<p>eCommerceGo SaaS offers a robust Import/Export Module designed to streamline the complexities of global trade. Whether you are importing raw materials or exporting finished products, our platform simplifies the process with user-friendly tools. Easily manage data transfer and product shipments across borders, ensuring smooth transactions and compliance with international trade regulations. From uploading supplier catalogs to exporting customer orders, our module supports seamless operations to enhance your business efficiency.</p>', 'ImportExport', '2026-06-10 16:33:48', '2026-06-10 16:33:48'),
(557, 'product_main_demo_link', '#', 'ImportExport', '2026-06-10 16:33:48', '2026-06-10 16:33:48'),
(558, 'product_main_demo_button_text', 'View Live Demo', 'ImportExport', '2026-06-10 16:33:48', '2026-06-10 16:33:48'),
(559, 'dedicated_theme_heading', 'Comprehensive Data Management', 'ImportExport', '2026-06-10 16:33:48', '2026-06-10 16:33:48'),
(560, 'dedicated_theme_description', '<p>Take control of your import and export processes with eCommerceGo SaaS. Our module facilitates easy data handling, allowing you to upload, update, and synchronize information effortlessly. Maintain accuracy in inventory records, pricing details, and shipment statuses to optimize supply chain management. By centralizing data management, businesses can minimize errors, improve decision-making, and respond promptly to market demands.</p>', 'ImportExport', '2026-06-10 16:33:48', '2026-06-10 16:33:48'),
(561, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Flexible Configuration Options\",\"dedicated_theme_section_description\":\"Customize import and export settings to align with your business strategies and operational requirements. eCommerceGo SaaS empowers users to adjust currency conversions, shipping methods, and tax considerations with ease. Adapt swiftly to changing market conditions and regulatory frameworks, ensuring compliance and optimizing cost-efficiency in global trade operations. Our flexible configuration options cater to diverse business needs, supporting seamless integration with existing workflows.\"},\n\n        {\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Real-Time Monitoring and Analytics\",\"dedicated_theme_section_description\":\"Gain actionable insights with real-time monitoring of import and export activities. Track shipment statuses, analyze sales trends, and forecast demand to make informed business decisions. eCommerceGo SaaS provides comprehensive analytics tools that empower businesses to optimize inventory levels, improve supply chain efficiency, and enhance customer satisfaction. Monitor performance metrics and streamline operations to drive growth and profitability in international markets.\"}]', 'ImportExport', '2026-06-10 16:33:48', '2026-06-10 16:33:48'),
(562, 'dedicated_theme_sections_heading', '', 'ImportExport', '2026-06-10 16:33:48', '2026-06-10 16:33:48'),
(563, 'screenshots', '[{\"screenshots\":\"\",\"screenshots_heading\":\"ImportExport\"},{\"screenshots\":\"\",\"screenshots_heading\":\"ImportExport\"},{\"screenshots\":\"\",\"screenshots_heading\":\"ImportExport\"},{\"screenshots\":\"\",\"screenshots_heading\":\"ImportExport\"},{\"screenshots\":\"\",\"screenshots_heading\":\"ImportExport\"}]', 'ImportExport', '2026-06-10 16:33:48', '2026-06-10 16:33:48'),
