(576, 'product_main_banner', '', 'LotteryPrizes', '2026-06-10 16:33:49', '2026-06-10 16:33:49'),
(577, 'product_main_status', 'on', 'LotteryPrizes', '2026-06-10 16:33:49', '2026-06-10 16:33:49'),
(578, 'product_main_heading', 'LotteryPrizes Add-On for E-commerceGo', 'LotteryPrizes', '2026-06-10 16:33:49', '2026-06-10 16:33:49'),
(579, 'product_main_description', '<p>Boost engagement and sales on your platform with the LotteryPrizes Add-On. This exciting feature allows you to create customizable lottery campaigns, where customers can win exclusive prizes, discounts, or rewards while shopping.</p>', 'LotteryPrizes', '2026-06-10 16:33:49', '2026-06-10 16:33:49'),
(580, 'product_main_demo_link', '#', 'LotteryPrizes', '2026-06-10 16:33:49', '2026-06-10 16:33:49'),
(581, 'product_main_demo_button_text', 'View Live Demo', 'LotteryPrizes', '2026-06-10 16:33:49', '2026-06-10 16:33:49'),
(582, 'dedicated_theme_heading', 'Engage Your Customers', 'LotteryPrizes', '2026-06-10 16:33:49', '2026-06-10 16:33:49'),
(583, 'dedicated_theme_description', '<p>Turn casual shoppers into loyal customers by offering fun, interactive lottery events. With LotteryPrizes, you can add a layer of excitement to the shopping experience, encouraging repeat visits and boosting user engagement.</p>', 'LotteryPrizes', '2026-06-10 16:33:49', '2026-06-10 16:33:49'),
(584, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Customizable Campaigns\",\"dedicated_theme_section_description\":\"Design lotteries that suit your business goals. Set prize types, eligibility criteria, and the duration of each campaign with ease. Whether it’s a seasonal sale or a promotional event, the flexibility of this add-on makes it perfect for all occasions.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Drive More Sales\",\"dedicated_theme_section_description\":\"Incentivize purchases by offering entry into lotteries for every product bought. This not only increases sales but also enhances customer satisfaction, as they enjoy added value with every transaction.\"}]', 'LotteryPrizes', '2026-06-10 16:33:49', '2026-06-10 16:33:49'),
(585, 'dedicated_theme_sections_heading', '', 'LotteryPrizes', '2026-06-10 16:33:49', '2026-06-10 16:33:49'),
