INSERT INTO `marketplace_page_settings` (`id`, `name`, `value`, `module`, `created_at`, `updated_at`) VALUES
(593, 'pricing_plan_description', '<p>Access over Premium Add-ons for Product Enquiry, Product Review, Product Quick-view, and more, all in one place!</p>', 'LotteryPrizes', '2026-06-10 16:33:49', '2026-06-10 16:33:49'),
(594, 'pricing_plan_demo_link', '#', 'LotteryPrizes', '2026-06-10 16:33:49', '2026-06-10 16:33:49'),
(595, 'pricing_plan_demo_button_text', 'View Live Demo', 'LotteryPrizes', '2026-06-10 16:33:49', '2026-06-10 16:33:49'),
(596, 'pricing_plan_text', '{\"1\":{\"title\":\"Pay-as-you-go\"},\"2\":{\"title\":\"Unlimited installation\"},\"3\":{\"title\":\"Secure cloud storage\"}}', 'LotteryPrizes', '2026-06-10 16:33:49', '2026-06-10 16:33:49'),
