(760, 'product_main_banner', '', 'ProductCatelog', '2026-06-10 16:46:07', '2026-06-10 16:46:07'),
(761, 'product_main_status', 'on', 'ProductCatelog', '2026-06-10 16:46:07', '2026-06-10 16:46:07'),
(762, 'product_main_heading', 'Product Catelog', 'ProductCatelog', '2026-06-10 16:46:07', '2026-06-10 16:46:07'),
(763, 'product_main_description', '<p>Our Product Catalog Module in eCommerceGo SaaS offers a streamlined approach to managing catalog requests. Through our intuitive interface, users can create custom email templates tailored to specific modules, ensuring customers receive relevant product information. With organized lists of requests, businesses can efficiently prioritize and respond to customer inquiries, ultimately enhancing customer satisfaction and engagement.</p>', 'ProductCatelog', '2026-06-10 16:46:07', '2026-06-10 16:46:07'),
(764, 'product_main_demo_link', '#', 'ProductCatelog', '2026-06-10 16:46:07', '2026-06-10 16:46:07'),
(765, 'product_main_demo_button_text', 'View Live Demo', 'ProductCatelog', '2026-06-10 16:46:07', '2026-06-10 16:46:07'),
(766, 'dedicated_theme_heading', 'Streamlined Product Catalogs Management', 'ProductCatelog', '2026-06-10 16:46:07', '2026-06-10 16:46:07'),
(767, 'dedicated_theme_description', '<p>Product Catalog Module in eCommerceGo SaaS offers a streamlined approach to managing catalog requests and its provide product details related to cateory in email. we can provide product detail through mail in your requested email address.</p>', 'ProductCatelog', '2026-06-10 16:46:07', '2026-06-10 16:46:07'),
(768, 'dedicated_theme_sections', '[\n            {\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Custom Email Templates for Every Module\",\"dedicated_theme_section_description\":\"Designing personalized email templates is made easy with our module. Whether your eCommerce store sells fashion, electronics, or home goods, you can create templates that resonate with your product range. These templates ensure that customers receive catalogs that are tailored to their interests, increasing the likelihood of conversions. From sleek electronics to trendy fashion, our customizable templates cater to diverse product categories.\"},\n            {\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Efficient Request Tracking and Management\",\"dedicated_theme_section_description\":\"Track and manage catalog requests effortlessly with our modules comprehensive features. Access a centralized list of requests, organized by module, allowing you to stay on top of customer inquiries. This organized approach ensures timely responses and prevents requests from falling through the cracks. With efficient request management, you can focus on providing excellent customer service and growing your business.\"},\n            {\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Convenient Frontend Request Submission\",\"dedicated_theme_section_description\":\"Empower your customers with convenient front-end request submission. Our module allows users to easily send catalog requests directly from the frontend interface. This seamless process enhances user experience and encourages customers to explore your product offerings further. By simplifying the request process, you increase customer engagement and satisfaction, ultimately driving sales and revenue.\"},\n            {\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Enhancing User Experience and Engagement\",\"dedicated_theme_section_description\":\"The Product Catalog Module doesnot just streamline internal processes; it also enhances user experience and engagement. By providing customers with relevant product catalogs tailored to their interests, you create a more personalized shopping experience. This increases customer satisfaction and encourages repeat purchases. With eCommerceGo SaaS, you can take your eCommerce business to new heights by delivering exceptional service and engagement to your customers. <\\/p>\"}]', 'ProductCatelog', '2026-06-10 16:46:07', '2026-06-10 16:46:07'),
(769, 'dedicated_theme_sections_heading', '', 'ProductCatelog', '2026-06-10 16:46:07', '2026-06-10 16:46:07'),
