(782, 'dedicated_theme_section_status', 'on', 'ProductCatelog', '2026-06-10 16:46:07', '2026-06-10 16:46:07'),
(783, 'product_main_banner', '', 'ProductCompare', '2026-06-10 16:47:04', '2026-06-10 16:47:04'),
