(785, 'product_main_heading', 'Product Compare', 'ProductCompare', '2026-06-10 16:47:04', '2026-06-10 16:47:04'),
(786, 'product_main_description', '<p>Introducing the Product Compare module by eCommerceGo SaaS, designed to simplify your product evaluation journey. We understand that making informed purchasing decisions is crucial. That is why we have developed an intuitive feature that allows you to effortlessly explore product details, enabling you to assess their features, specifications, and prices conveniently.</p>', 'ProductCompare', '2026-06-10 16:47:04', '2026-06-10 16:47:04'),
(787, 'product_main_demo_link', '#', 'ProductCompare', '2026-06-10 16:47:04', '2026-06-10 16:47:04'),
(788, 'product_main_demo_button_text', 'View Live Demo', 'ProductCompare', '2026-06-10 16:47:04', '2026-06-10 16:47:04'),
(789, 'dedicated_theme_heading', 'Seamless Evaluation Process', 'ProductCompare', '2026-06-10 16:47:04', '2026-06-10 16:47:04'),
(790, 'dedicated_theme_description', '<p>With Product Compare, exploring products is a breeze. Our user-friendly interface lets you view detailed product information in a structured and organized manner. Whether you are researching electronics, clothing, or home goods, our module simplifies the evaluation process by presenting relevant details in an easy-to-navigate format.</p>', 'ProductCompare', '2026-06-10 16:47:04', '2026-06-10 16:47:04'),
(791, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Comprehensive Product Details\",\"dedicated_theme_section_description\":\"Make well-informed decisions with our comprehensive product details. From technical specifications to product descriptions and pricing information, our module provides you with all the essential information you need to evaluate products effectively. With just a few clicks, you can explore product features, availability, and pricing, empowering you to make informed choices that align with your needs.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Personalized Exploration Experience\",\"dedicated_theme_section_description\":\"Tailor your exploration experience to suit your preferences. With customizable viewing options, you can focus on the details that matter most to you. Whether you are interested in specific product features, pricing tiers, or availability status, our module allows you to adjust the viewing settings to align with your priorities, ensuring that you can explore products at your own pace.\"}]', 'ProductCompare', '2026-06-10 16:47:04', '2026-06-10 16:47:04'),
(792, 'dedicated_theme_sections_heading', '', 'ProductCompare', '2026-06-10 16:47:04', '2026-06-10 16:47:04'),
