(944, 'product_main_banner', '', 'ProductsPDF', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(945, 'product_main_status', 'on', 'ProductsPDF', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(946, 'product_main_heading', 'Products PDF', 'ProductsPDF', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(947, 'product_main_description', '<p>In the competitive world of eCommerce, presenting your products in the best light is crucial. The Product PDF Module of eCommerceGo SaaS empowers you to create stunning, professional-grade PDF documents for each of your products. These PDFs can include detailed descriptions, high-resolution images, pricing information, and specifications, providing your customers with a comprehensive overview in an easy-to-read format. By offering downloadable PDFs, you enhance the shopping experience, making it easier for customers to review and share product information.</p>', 'ProductsPDF', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(948, 'product_main_demo_link', '#', 'ProductsPDF', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(949, 'product_main_demo_button_text', 'View Live Demo', 'ProductsPDF', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(950, 'dedicated_theme_heading', 'Accuracy and Effortlessly', 'ProductsPDF', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(951, 'dedicated_theme_description', '<p>Generate and share detailed product PDFs effortlessly with the Product PDF module of eCommerceGo SaaS.</p>', 'ProductsPDF', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(952, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Enhance Customer Engagement and Retention\",\"dedicated_theme_section_description\":\"Providing detailed and visually appealing product information can significantly enhance customer engagement and retention. The Product PDF Module allows you to include rich media elements such as images and interactive links within your PDFs, making the documents more engaging. Customers are more likely to spend time reviewing products and making informed purchasing decisions when they have access to high-quality, detailed information. This level of engagement helps build customer trust and loyalty, encouraging repeat business.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Easy Integration and Automation\",\"dedicated_theme_section_description\":\"Seamlessly integrate the Product PDF Module with your existing eCommerce platform to streamline the creation and distribution of product PDFs. Our module supports automated generation of PDFs based on your product catalog, ensuring that every product page on your website has an up-to-date downloadable PDF. This automation saves you time and effort, allowing you to focus on other critical aspects of your business. Additionally, it ensures that your customers always have access to the latest product information.\"}]', 'ProductsPDF', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(953, 'dedicated_theme_sections_heading', '', 'ProductsPDF', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
