(967, 'product_main_banner', '', 'PurchaseNotification', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(968, 'product_main_status', 'on', 'PurchaseNotification', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(969, 'product_main_heading', 'Purchase Notification', 'PurchaseNotification', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(970, 'product_main_description', '<p>Simplify your customer communication process with eCommerceGo SaaSs purchase notification module. Our platform automates the process of sending order updates to your customers, ensuring they are always in the know. Saving you time and effort.</p>', 'PurchaseNotification', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(971, 'product_main_demo_link', '#', 'PurchaseNotification', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(972, 'product_main_demo_button_text', 'View Live Demo', 'PurchaseNotification', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(973, 'dedicated_theme_heading', 'Efficiency and Accuracy', 'PurchaseNotification', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(974, 'dedicated_theme_description', '<p>eCommerceGo SaaS purchase notification module synchronizes order data in real-time, reducing the risk of errors and ensuring accuracy. Seamlessly integrate with your existing order management system for maximum efficiency. Whether you are processing orders through your eCommerce platform or third-party channels, our module ensures that purchase notifications are sent promptly and accurately.</p>', 'PurchaseNotification', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(975, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Real-Time Status Updates\",\"dedicated_theme_section_description\":\"Keep your customers informed every step of the way with real-time order updates from eCommerceGo SaaS. Whether its confirming an order, processing it, or providing tracking information, our module ensures your customers receive timely notifications. Say goodbye to manual notifications and hello to automated efficiency with eCommerceGo SaaS.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Enhanced Customer Experience\",\"dedicated_theme_section_description\":\"By providing automated order updates, eCommerceGo SaaS helps enhance the overall customer experience. Keep your customers informed, satisfied, and coming back for more with timely and accurate notifications. With eCommerceGo SaaS, you can streamline your communication process and delight your customers with exceptional service.\"}]', 'PurchaseNotification', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(976, 'dedicated_theme_sections_heading', '', 'PurchaseNotification', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
