(984, 'pricing_plan_description', '<p>Access over Premium Add-ons for Product Enquiry, Product Review, Product Quick-view, and more, all in one place!</p>', 'PurchaseNotification', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
