(986, 'pricing_plan_demo_button_text', 'View Live Demo', 'PurchaseNotification', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(987, 'pricing_plan_text', '{\"1\":{\"title\":\"Pay-as-you-go\"},\"2\":{\"title\":\"Unlimited installation\"},\"3\":{\"title\":\"Secure cloud storage\"}}', 'PurchaseNotification', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
