(989, 'dedicated_theme_section_status', 'on', 'PurchaseNotification', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(990, 'product_main_banner', '', 'QuickCheckout', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(991, 'product_main_status', 'on', 'QuickCheckout', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(992, 'product_main_heading', 'Quick Checkout', 'QuickCheckout', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(993, 'product_main_description', '<p>The QuickCheckOut module of eCommerceGo revolutionizes the way customers complete their purchases. Designed with user convenience in mind, it minimizes the steps required to finalize a transaction. By reducing the number of clicks and form fields, QuickCheckOut ensures a smooth, efficient process that encourages customers to complete their purchases without hesitation. This streamlined approach not only improves the customer experience but also reduces cart abandonment rates, leading to higher conversion rates and increased sales.</p>', 'QuickCheckout', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(994, 'product_main_demo_link', '#', 'QuickCheckout', '2026-06-10 16:54:43', '2026-06-10 16:54:43'),
(995, 'product_main_demo_button_text', 'View Live Demo', 'QuickCheckout', '2026-06-10 16:54:44', '2026-06-10 16:54:44'),
(996, 'dedicated_theme_heading', 'Streamlined Purchasing Experience', 'QuickCheckout', '2026-06-10 16:54:44', '2026-06-10 16:54:44'),
(997, 'dedicated_theme_description', '<p>The QuickCheckout module of eCommerceGo SaaS streamlines the checkout process, offering customers a swift and hassle-free experience, ultimately boosting conversions and sales.</p>', 'QuickCheckout', '2026-06-10 16:54:44', '2026-06-10 16:54:44'),
(998, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Secure Payment Gateway\",\"dedicated_theme_section_description\":\"Security is a top priority for eCommerceGo, and the QuickCheckOut module reflects this commitment. Integrated with advanced encryption technologies and secure payment gateways, it ensures that all transactions are protected against fraud and unauthorized access. Customers can confidently enter their payment details, knowing that their sensitive information is safe. By providing a secure checkout environment, eCommerceGo helps build trust and loyalty among customers, encouraging repeat business.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"User-Friendly Interface\",\"dedicated_theme_section_description\":\"The QuickCheckOut module features an intuitive and user-friendly interface that caters to all types of customers, whether they are tech-savvy or less experienced with online shopping. The interface is designed to be clean and clutter-free, with clear instructions and easily navigable steps. This simplicity helps reduce confusion and frustration, allowing customers to quickly and effortlessly complete their purchases. The user-friendly design ensures that the checkout process is accessible and enjoyable for everyone.\"}]', 'QuickCheckout', '2026-06-10 16:54:44', '2026-06-10 16:54:44'),
(999, 'dedicated_theme_sections_heading', '', 'QuickCheckout', '2026-06-10 16:54:44', '2026-06-10 16:54:44'),
