(1038, 'product_main_heading', 'Recent Orders', 'RecentOrders', '2026-06-10 16:56:01', '2026-06-10 16:56:01'),
(1039, 'product_main_description', '<p>Integrate our Recent Orders Module into your eCommerceGo SaaS platform to offer personalized order insights to your customers. Once enabled by the admin, this feature allows customers to view their own recent orders as they proceed with new purchases. By displaying a customers specific order history, you enhance their shopping experience and foster trust in your platform.</p>', 'RecentOrders', '2026-06-10 16:56:01', '2026-06-10 16:56:01'),
(1040, 'product_main_demo_link', '#', 'RecentOrders', '2026-06-10 16:56:01', '2026-06-10 16:56:01'),
(1041, 'product_main_demo_button_text', 'View Live Demo', 'RecentOrders', '2026-06-10 16:56:01', '2026-06-10 16:56:01'),
(1042, 'dedicated_theme_heading', 'Real-Time Personal Order History', 'RecentOrders', '2026-06-10 16:56:01', '2026-06-10 16:56:01'),
(1043, 'dedicated_theme_description', '<p>With the Recent Orders Module enabled, customers can access their own recent order history in real-time. When placing a new order, they all see a list of their most recent purchases, providing valuable context and convenience. This personal touch ensures customers are always informed and empowered during their shopping journey.</p>', 'RecentOrders', '2026-06-10 16:56:01', '2026-06-10 16:56:01'),
(1044, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Customizable Display Settings\",\"dedicated_theme_section_description\":\"Admins have the flexibility to customize the number of recent orders displayed for each customer. For example, if an admin selects 5 orders, the customer will see their five most recent purchases when placing a new order. This customizable feature ensures a tailored experience for each individual, enhancing usability and satisfaction.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Enhanced User Engagement\",\"dedicated_theme_section_description\":\"By offering personalized order insights, the Recent Orders Module enhances user engagement and satisfaction. Customers feel more connected to your platform when they can easily track their own order history, leading to increased loyalty and repeat business. This feature encourages customers to explore more products and complete their purchases with confidence.\"}]', 'RecentOrders', '2026-06-10 16:56:01', '2026-06-10 16:56:01'),
(1045, 'dedicated_theme_sections_heading', '', 'RecentOrders', '2026-06-10 16:56:01', '2026-06-10 16:56:01'),
