(1107, 'product_main_heading', 'SidebarCustomization', 'SidebarCustomization', '2026-06-10 17:02:16', '2026-06-10 17:02:16'),
(1108, 'product_main_description', '<p>The Sidebar Customization Add-On for eCommerceGo SaaS lets you design and personalize your website is sidebar with ease. This powerful feature ensures seamless navigation, enhances user experience, and aligns your site’s layout with your brand identity.</p>', 'SidebarCustomization', '2026-06-10 17:02:16', '2026-06-10 17:02:16'),
(1109, 'product_main_demo_link', '#', 'SidebarCustomization', '2026-06-10 17:02:16', '2026-06-10 17:02:16'),
(1110, 'product_main_demo_button_text', 'View Live Demo', 'SidebarCustomization', '2026-06-10 17:02:16', '2026-06-10 17:02:16'),
(1111, 'dedicated_theme_heading', 'Fully Customizable Layout', 'SidebarCustomization', '2026-06-10 17:02:16', '2026-06-10 17:02:16'),
(1112, 'dedicated_theme_description', '<p>Tailor your sidebar to suit your website is needs. Add, remove, or reorder sections to prioritize the most relevant information for your users. Whether it’s quick links, product categories, or promotional banners, you have complete control over what your sidebar displays.</p>', 'SidebarCustomization', '2026-06-10 17:02:16', '2026-06-10 17:02:16'),
(1113, 'dedicated_theme_sections', '[\n                                                {\n                                                    \"dedicated_theme_section_image\": \"\",\n                                                    \"dedicated_theme_section_heading\": \"Brand-Consistent Design\",\n                                                    \"dedicated_theme_section_description\": \"Maintain consistency across your website by customizing the sidebar’s appearance to reflect your brand. You can modify colors, fonts, and icons to create a cohesive design that enhances your site’s professionalism and visual appeal.\",\n                                                    \"dedicated_theme_section_cards\": {\n                                                    \"1\": {\n                                                        \"title\": \"Improved User Experience\",\n                                                        \"description\": \"A well-organized sidebar makes navigation easy for your customers. By highlighting key areas like new arrivals, popular products, or ongoing offers, you can guide users through your site effectively and boost engagement.\"\n                                                    },\n                                                    \"2\": {\n                                                    \"title\": \"Quick and Easy Setup\",\n                                                        \"description\": \"Setting up the Sidebar Customization Add-On is simple and intuitive. With just a few clicks, you can create a sidebar that complements your website’s design and improves its functionality. It’s a small change that can have a big impact on customer satisfaction and sales.\"\n                                                    }\n                                                    }\n                                                }\n                                            ]', 'SidebarCustomization', '2026-06-10 17:02:16', '2026-06-10 17:02:16'),
