(1171, 'pricing_plan_text', '{\"1\":{\"title\":\"Pay-as-you-go\"},\"2\":{\"title\":\"Unlimited installation\"},\"3\":{\"title\":\"Secure cloud storage\"}}', 'SignInWithFacebook', '2026-06-10 17:05:20', '2026-06-10 17:05:20'),
