(1245, 'product_main_heading', 'Sign In With Slack', 'SignInWithSlack', '2026-06-10 17:08:18', '2026-06-10 17:08:18'),
(1246, 'product_main_description', '<p>Sign In with Slack module is designed to provide a seamless integration with Slack, enabling you to access our platform with just a single click. By leveraging your existing Slack credentials, you can bypass the traditional sign-in process and gain instant access to all the powerful features and tools EcommerceGo offers. Saving you time and effort.</p>', 'SignInWithSlack', '2026-06-10 17:08:18', '2026-06-10 17:08:18'),
(1247, 'product_main_demo_link', '#', 'SignInWithSlack', '2026-06-10 17:08:18', '2026-06-10 17:08:18'),
(1248, 'product_main_demo_button_text', 'View Live Demo', 'SignInWithSlack', '2026-06-10 17:08:18', '2026-06-10 17:08:18'),
(1249, 'dedicated_theme_heading', 'Enhanced Security and Compliance', 'SignInWithSlack', '2026-06-10 17:08:18', '2026-06-10 17:08:18'),
(1250, 'dedicated_theme_description', '<p>Security is a top priority at EcommerceGo, and our Slack integration is built with robust security measures in place. By using OAuth 2.0 for authentication, we ensure that your credentials are protected and that the sign-in process is secure.</p>', 'SignInWithSlack', '2026-06-10 17:08:18', '2026-06-10 17:08:18'),
(1251, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\n        \"dedicated_theme_section_heading\":\"Streamlined Communication and Collaboration\",\n        \"dedicated_theme_section_description\":\"The \"Sign In with Slack\" module not only simplifies access but also enhances communication and collaboration within your team. Once signed in, users can receive real-time notifications from EcommerceGo directly in their Slack channels. This integration keeps your team informed about important updates, order statuses, and customer inquiries without having to switch between platforms.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Easy Setup and Customization\",\"dedicated_theme_section_description\":\"Setting up the \"Sign In with Slack\" integration is quick and straightforward. Our user-friendly interface guides you through the process, allowing you to connect your Slack workspace to EcommerceGo in just a few steps. Once connected, you can customize the integration to fit your specific needs, such as choosing which notifications to receive in Slack and defining user permissions.\"}]', 'SignInWithSlack', '2026-06-10 17:08:18', '2026-06-10 17:08:18'),
(1252, 'dedicated_theme_sections_heading', '', 'SignInWithSlack', '2026-06-10 17:08:18', '2026-06-10 17:08:18'),
