(1291, 'product_main_heading', 'SMS', 'SMS', '2026-06-10 17:11:42', '2026-06-10 17:11:42'),
(1292, 'product_main_description', '<p>Experience seamless SMS communication with eCommerceGo SaaS. Organize, send, and track messages effortlessly through trusted SMS gateways like AWS, Twilio, Clockwork, Melipayamak, Kavenegar, and SMS Gateway. </p>', 'SMS', '2026-06-10 17:11:42', '2026-06-10 17:11:42'),
(1293, 'product_main_demo_link', '#', 'SMS', '2026-06-10 17:11:42', '2026-06-10 17:11:42'),
(1294, 'product_main_demo_button_text', 'View Live Demo', 'SMS', '2026-06-10 17:11:42', '2026-06-10 17:11:42'),
(1295, 'dedicated_theme_heading', 'Categorize and Conquer: Effective Message Organization', 'SMS', '2026-06-10 17:11:42', '2026-06-10 17:11:42'),
(1296, 'dedicated_theme_description', '<p>Take control of your communication strategy by categorizing your messages within eCommerceGo SaaS. Whether it`s customer updates, transactional notifications, or promotional announcements, our platform allows you to organize your messages effectively. By categorizing messages, you can ensure that recipients receive relevant and targeted information, enhancing the overall user experience and engagement.</p>', 'SMS', '2026-06-10 17:11:42', '2026-06-10 17:11:42'),
(1297, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Trusted Providers, Seamless Integration\",\"dedicated_theme_section_description\":\"Our platform seamlessly integrates with leading SMS gateways, providing you with unparalleled reliability and delivery assurance. Whether you prefer AWS, Twilio, Clockwork, Melipayamak, Kavenegar, or another SMS gateway provider, eCommerceGo SaaS ensures seamless integration for uninterrupted communication. Leverage the infrastructure of trusted providers to ensure that your messages reach their intended recipients without fail.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Efficiency at Your Fingertips: Managing SMS Communication\",\"dedicated_theme_section_description\":\"With eCommerceGo SaaS, managing your SMS communication is a breeze. Our user-friendly interface empowers you to schedule messages, track delivery status, and analyze performance with ease. From message scheduling to delivery status tracking, our platform provides you with the tools you need to stay in control of your communication strategy. Join the ranks of satisfied users who have revolutionized their communication processes with eCommerceGo SaaS – sign up today and discover a new era of efficiency and effectiveness.\"}]', 'SMS', '2026-06-10 17:11:42', '2026-06-10 17:11:42'),
(1298, 'dedicated_theme_sections_heading', '', 'SMS', '2026-06-10 17:11:42', '2026-06-10 17:11:42'),
