(1335, 'product_main_banner', '', 'SpamPrevent', '2026-06-10 17:13:16', '2026-06-10 17:13:16'),
(1336, 'product_main_status', 'on', 'SpamPrevent', '2026-06-10 17:13:16', '2026-06-10 17:13:16'),
(1337, 'product_main_heading', 'SpamPrevent', 'SpamPrevent', '2026-06-10 17:13:16', '2026-06-10 17:13:16'),
(1338, 'product_main_description', '<p>The Spam Prevention Module for eCommerceGo SaaS streamlines customer interaction by providing a convenient commenting system directly on product pages. Customers can easily leave comments, whether it is to share their experience with a product, ask questions, or provide feedback. With a simple click of a button, they can engage with your brand, fostering a sense of community and trust.</p>', 'SpamPrevent', '2026-06-10 17:13:16', '2026-06-10 17:13:16'),
(1339, 'product_main_demo_link', '#', 'SpamPrevent', '2026-06-10 17:13:17', '2026-06-10 17:13:17'),
(1340, 'product_main_demo_button_text', 'View Live Demo', 'SpamPrevent', '2026-06-10 17:13:17', '2026-06-10 17:13:17'),
(1341, 'dedicated_theme_heading', 'Efficient Admin Management', 'SpamPrevent', '2026-06-10 17:13:17', '2026-06-10 17:13:17'),
(1342, 'dedicated_theme_description', '<p>Admins can efficiently manage customer comments both from the backend and the front end. From the backend dashboard, they can view and respond to comments, ensuring timely and personalized interactions. Additionally, our module allows admins to reply directly from the front end, saving time and streamlining the process.</p>', 'SpamPrevent', '2026-06-10 17:13:17', '2026-06-10 17:13:17'),
(1343, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Anonymous Admin Replies\",\"dedicated_theme_section_description\":\"One unique feature of our module is the ability for admins to reply anonymously if desired. By clicking on the refresh button, admins can refresh the page without triggering a notification to the customer. This feature gives admins the flexibility to handle interactions discreetly, maintaining professionalism and privacy when needed.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Clean and Spam-Free Environment\",\"dedicated_theme_section_description\":\"Say goodbye to spam with our Spam Prevention Module. We understand the frustration of dealing with unwanted and irrelevant comments cluttering your product pages. Our module filters out spammy comments, ensuring that only genuine customer feedback is visible. This creates a clean and spam-free environment where customers can engage with your products without distractions.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Enhanced User Experience\",\"dedicated_theme_section_description\":\"<p>Ultimately, the Spam Prevention Module enhances the user experience on your eCommerce platform. By keeping the comments section clean and relevant, customers can easily find valuable information and engage with your brand. Prompt and personalized responses from admins foster trust and loyalty, leading to a positive overall experience for both customers and admins alike. Upgrade to our module today and elevate your eCommerce commenting experience!<\\/p>\"}]', 'SpamPrevent', '2026-06-10 17:13:17', '2026-06-10 17:13:17'),
(1344, 'dedicated_theme_sections_heading', '', 'SpamPrevent', '2026-06-10 17:13:17', '2026-06-10 17:13:17'),
