(1360, 'product_main_heading', 'Spin To Win Reward', 'SpinToWinReward', '2026-06-10 17:14:50', '2026-06-10 17:14:50'),
(1361, 'product_main_description', '<p>The Spin to Win Reward module of eCommerceGo SaaS revolutionizes customer engagement by introducing an interactive element to the online shopping experience. With this innovative feature, businesses can captivate their audience and incentivize purchases through an exciting spin wheel game. By gamifying the shopping process, the module creates a sense of anticipation and fun, driving increased customer interaction and loyalty.</p>', 'SpinToWinReward', '2026-06-10 17:14:50', '2026-06-10 17:14:50'),
(1362, 'product_main_demo_link', '#', 'SpinToWinReward', '2026-06-10 17:14:50', '2026-06-10 17:14:50'),
(1363, 'product_main_demo_button_text', 'View Live Demo', 'SpinToWinReward', '2026-06-10 17:14:50', '2026-06-10 17:14:50'),
(1364, 'dedicated_theme_heading', 'Engage Customers with Interactive Rewards', 'SpinToWinReward', '2026-06-10 17:14:50', '2026-06-10 17:14:50'),
(1365, 'dedicated_theme_description', '<p>The Spin to Win Reward module of eCommerceGo SaaS adds an interactive element to your online store, enticing customers with exciting prizes and incentives through a fun and engaging spin wheel game.</p>', 'SpinToWinReward', '2026-06-10 17:14:50', '2026-06-10 17:14:50'),
(1366, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Exciting Prizes and Incentives\",\"dedicated_theme_section_description\":\"Customers are enticed to participate in the spin wheel game with the promise of exciting prizes and incentives. Whether its discounts, freebies, or exclusive offers, the Spin to Win Reward module offers a variety of rewards to appeal to different preferences and motivations. This element of surprise adds an extra layer of excitement to the shopping journey, encouraging repeat visits and purchases.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Drive Conversions and Sales\",\"dedicated_theme_section_description\":\"Ultimately, the Spin to Win Reward module is designed to drive conversions and sales for businesses. By leveraging the element of gamification and offering enticing rewards, businesses can encourage customers to complete their purchases and increase their order value. The module not only enhances the shopping experience but also delivers tangible results in terms of revenue growth and customer satisfaction.\"}]', 'SpinToWinReward', '2026-06-10 17:14:50', '2026-06-10 17:14:50'),
(1367, 'dedicated_theme_sections_heading', '', 'SpinToWinReward', '2026-06-10 17:14:50', '2026-06-10 17:14:50'),
