(1381, 'product_main_banner', '', 'StoreLocator', '2026-06-10 17:16:19', '2026-06-10 17:16:19'),
(1382, 'product_main_status', 'on', 'StoreLocator', '2026-06-10 17:16:19', '2026-06-10 17:16:19'),
(1383, 'product_main_heading', 'Store Locator', 'StoreLocator', '2026-06-10 17:16:19', '2026-06-10 17:16:19'),
(1384, 'product_main_description', '<p>The Store Locator Module of eCommerceGo SaaS elevates the customer experience by providing an intuitive and convenient way for shoppers to find physical store locations. With this module, businesses can bridge the gap between online and offline shopping, empowering customers to easily locate nearby stores and make informed purchase decisions.</p>', 'StoreLocator', '2026-06-10 17:16:19', '2026-06-10 17:16:19'),
(1385, 'product_main_demo_link', '#', 'StoreLocator', '2026-06-10 17:16:19', '2026-06-10 17:16:19'),
(1386, 'product_main_demo_button_text', 'View Live Demo', 'StoreLocator', '2026-06-10 17:16:19', '2026-06-10 17:16:19'),
(1387, 'dedicated_theme_heading', 'Enhanced Customer Experience', 'StoreLocator', '2026-06-10 17:16:19', '2026-06-10 17:16:19'),
(1388, 'dedicated_theme_description', '<p>The Store Locator Module of eCommerceGo SaaS enables customers to easily find and navigate to physical store locations, enhancing convenience and driving foot traffic for businesses.</p>', 'StoreLocator', '2026-06-10 17:16:19', '2026-06-10 17:16:19'),
(1389, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Seamless Integration with Online Stores\",\"dedicated_theme_section_description\":\"Integrating seamlessly with online stores, the Store Locator Module allows businesses to display store locations directly on their e-commerce websites. Customers can access the store locator tool from any device, including desktops, tablets, and smartphones, ensuring accessibility and convenience. By offering this feature, businesses can enhance the overall shopping experience and drive foot traffic to their physical locations.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Interactive Mapping Functionality\",\"dedicated_theme_section_description\":\"The Store Locator Module offers interactive mapping functionality, enabling customers to visually explore store locations and surrounding areas. Through dynamic maps, customers can view detailed directions, check store hours, and discover nearby amenities such as parking facilities and public transportation options. This interactive approach enhances engagement and provides customers with valuable information to plan their shopping trips effectively.\"}]', 'StoreLocator', '2026-06-10 17:16:19', '2026-06-10 17:16:19'),
(1390, 'dedicated_theme_sections_heading', '', 'StoreLocator', '2026-06-10 17:16:19', '2026-06-10 17:16:19'),
