(1406, 'product_main_heading', 'Subscribe', 'Subscribe', '2026-06-10 17:18:43', '2026-06-10 17:18:43'),
(1407, 'product_main_description', '<p>With a sleek and eye-catching design, our Subscribe Popup grabs the attention of your website visitors immediately. Whether browsing your product pages or about to exit your site, the popup ensures they take advantage of the opportunity to subscribe to your newsletter.</p>', 'Subscribe', '2026-06-10 17:18:43', '2026-06-10 17:18:43'),
