(1475, 'product_main_heading', 'WholesaleProduct', 'WholesaleProduct', '2026-06-10 17:20:13', '2026-06-10 17:20:13'),
(1476, 'product_main_description', '<p>The Wholesale Module of eCommerceGo SaaS offers a seamless solution for managing bulk orders and wholesale pricing. This powerful tool simplifies the process of adding multiple products with their respective wholesale prices, providing flexibility and efficiency in wholesale operations.</p>', 'WholesaleProduct', '2026-06-10 17:20:13', '2026-06-10 17:20:13'),
(1477, 'product_main_demo_link', '#', 'WholesaleProduct', '2026-06-10 17:20:13', '2026-06-10 17:20:13'),
(1478, 'product_main_demo_button_text', 'View Live Demo', 'WholesaleProduct', '2026-06-10 17:20:13', '2026-06-10 17:20:13'),
(1479, 'dedicated_theme_heading', 'Streamlined Product Management', 'WholesaleProduct', '2026-06-10 17:20:13', '2026-06-10 17:20:13'),
(1480, 'dedicated_theme_description', '<p>Adding products with wholesale pricing is incredibly straightforward with our intuitive interface. You can effortlessly input details for each product along with its wholesale price. Whether you are selling electronics, clothing, or accessories, our module makes it easy to manage your wholesale product catalog with precision.</p>', 'WholesaleProduct', '2026-06-10 17:20:13', '2026-06-10 17:20:13'),
(1481, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Flexible Wholesale Pricing\",\"dedicated_theme_section_description\":\"Set wholesale prices to cater to your bulk orders and wholesale clients. Our module offers flexibility in pricing, allowing you to provide competitive rates while ensuring profitability. Whether you prefer tiered pricing based on quantity or fixed wholesale rates, our system can adapt to your pricing strategy seamlessly.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Enhanced Order Processing\",\"dedicated_theme_section_description\":\"Processing wholesale orders becomes a breeze with our module. Wholesale customers can conveniently place bulk orders through your eCommerce storefront, selecting the quantities they require at the wholesale prices you have set. This streamlined ordering process enhances the buying experience for your wholesale clients and simplifies order fulfillment on your end.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Comprehensive Reporting and Management\",\"dedicated_theme_section_description\":\"<p>Track your wholesale sales and performance effortlessly with comprehensive reporting features. Our module provides detailed insights into wholesale orders, enabling you to monitor sales trends, track inventory levels, and analyze customer behavior. Armed with this valuable data, you can make informed decisions to optimize your wholesale operations and drive business growth.<\\/p>\"}]', 'WholesaleProduct', '2026-06-10 17:20:13', '2026-06-10 17:20:13'),
(1482, 'dedicated_theme_sections_heading', '', 'WholesaleProduct', '2026-06-10 17:20:13', '2026-06-10 17:20:13'),
