(1498, 'product_main_heading', 'Wizzchat', 'Wizzchat', '2026-06-10 17:33:08', '2026-06-10 17:33:08'),
(1499, 'product_main_description', '<p>Integrating WizzChat Bot into your eCommerceGo platform is a seamless process that significantly enhances your customer service capabilities. WizzChat is a powerful tool designed to streamline communication between your business and your customers, offering real-time assistance and automated responses. This guide will walk you through the necessary steps to successfully integrate WizzChat into your eCommerceGo settings, ensuring that your customers receive timely and efficient support.</p>', 'Wizzchat', '2026-06-10 17:33:08', '2026-06-10 17:33:08'),
