(1502, 'dedicated_theme_heading', '<h2>Integrating <b>Wizzchat Module</b> with eCommerceGo Saas</h2>', 'Wizzchat', '2026-06-10 17:33:08', '2026-06-10 17:33:08'),
(1503, 'dedicated_theme_description', '<p>Integrating Wizzchat with eCommerceGo Saas is a seamless process that enhances your customer support and interaction capabilities.Follow these simple steps to integrate Wizzchat into your eCommerceGo Saas platform.</p>', 'Wizzchat', '2026-06-10 17:33:08', '2026-06-10 17:33:08'),
(1504, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Accessing Your eCommerceGo Settings\",\"dedicated_theme_section_description\":\"To begin, log in to your eCommerceGo dashboard using your administrator credentials. Once logged in, navigate to the settings section, which is typically found in the main menu. The settings section is the control center for your eCommerceGo platform, allowing you to customize various aspects of your online store. Look for a module labeled \"Chat Integrations\" or specifically for \"WizzChat\" within this section. This is where you will manage the integration process.\",\"dedicated_theme_section_cards\":{\"1\":{\"title\":null,\"description\":null}}},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Obtaining and Pasting the WizzChat Code\",\"dedicated_theme_section_description\":\"Next, you will need to obtain the integration code from the WizzChat website. Log in to your WizzChat account and navigate to the integration or API settings. Here, you will find a unique code provided by WizzChat specifically for your account. Copy this code to your clipboard. Return to your eCommerceGo settings and locate the WizzChat integration module. In the designated field, paste the copied WizzChat code. This step connects your WizzChat account with your eCommerceGo platform, enabling the chatbot functionality.\",\"dedicated_theme_section_cards\":{\"1\":{\"title\":null,\"description\":null}}},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Verifying and Utilizing the WizzChat Bot\",\"dedicated_theme_section_description\":\"Finally, verify that the WizzChat Bot has been successfully integrated by navigating back to your eCommerceGo dashboard. You should now see the WizzChat Bot active in your settings, ready to assist customers. Additionally, you can visit your live site to see the chatbot in action. With WizzChat integrated, your customers can enjoy real-time assistance, improving their overall shopping experience and increasing customer satisfaction. This integration not only boosts your support capabilities but also helps in maintaining a responsive and customer-friendly online store.\",\"dedicated_theme_section_cards\":{\"2\":{\"title\":null,\"description\":null}}}]', 'Wizzchat', '2026-06-10 17:33:08', '2026-06-10 17:33:08'),
(1505, 'dedicated_theme_sections_heading', '', 'Wizzchat', '2026-06-10 17:33:08', '2026-06-10 17:33:08'),
