(1544, 'product_main_heading', 'Count-Down Timer', 'CountDownTimer', '2026-06-10 23:18:00', '2026-06-10 23:18:00'),
(1545, 'product_main_description', '<p>Elevate your eCommerceGo SaaS platform with the Countdown Timer Module, a dynamic tool designed to create excitement and urgency around your upcoming sales events. With this feature, admins can easily set up countdown timers for sales directly from the store settings page, enhancing customer engagement and boosting sales.</p>', 'CountDownTimer', '2026-06-10 23:18:00', '2026-06-10 23:18:00'),
(1546, 'product_main_demo_link', '#', 'CountDownTimer', '2026-06-10 23:18:00', '2026-06-10 23:18:00'),
(1547, 'product_main_demo_button_text', 'View Live Demo', 'CountDownTimer', '2026-06-10 23:18:00', '2026-06-10 23:18:00'),
(1548, 'dedicated_theme_heading', 'Enhance Customer Experience', 'CountDownTimer', '2026-06-10 23:18:00', '2026-06-10 23:18:00'),
(1549, 'dedicated_theme_description', '<p>The Countdown Timer Module enhances the overall customer experience by providing clear and concise information about upcoming sales events.</p>', 'CountDownTimer', '2026-06-10 23:18:00', '2026-06-10 23:18:00'),
(1550, 'dedicated_theme_sections', '[{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Easy Setup and Customization\",\"dedicated_theme_section_description\":\"Admins can seamlessly configure countdown settings to suit their specific sales events. From the store settings page, they can specify the duration of the countdown, add a title, set the start date and time, provide a description, and even upload custom images for the sale and background. With a range of theme layouts to choose from, admins can customize the look and feel of the countdown timer to match their brand aesthetic.\"},{\"dedicated_theme_section_image\":\"\",\"dedicated_theme_section_heading\":\"Drive Sales with Urgency\",\"dedicated_theme_section_description\":\"By displaying countdown timers on the frontend of your eCommerceGo SaaS platform, you create a sense of urgency that motivates customers to act quickly. As the timer counts down, customers are reminded of the limited time remaining to take advantage of the sale, encouraging them to make a purchase before its too late. This urgency not only drives immediate sales but also increases overall conversion rates.\"}]', 'CountDownTimer', '2026-06-10 23:18:00', '2026-06-10 23:18:00'),
(1551, 'dedicated_theme_sections_heading', '', 'CountDownTimer', '2026-06-10 23:18:00', '2026-06-10 23:18:00'),
