INSERT INTO `templates` (`id`, `template_name`, `prompt`, `module`, `field_json`, `is_tone`, `created_at`, `updated_at`) VALUES
(1, 'name', '\"Create creative product names:  ##description## \\n\\nSeed words: ##keywords## \\n\\n\" in comma seprate and no number', 'products', '{\"field\":[{\"label\":\"Seed words\",\"placeholder\":\"e.g.  fast, healthy, compact\",\"field_type\":\"text_box\",\"field_name\":\"keywords\"},{\"label\":\"Product Description\",\"placeholder\":\"e.g. Provide product details\",\"field_type\":\"textarea\",\"field_name\":\"description\"}]}', 0, '2026-06-08 13:25:15', '2026-06-08 13:25:15'),
(2, 'description', 'Write a long creative product description for: ##title##', 'products', '{\"field\":[{\"label\":\"Product name\",\"placeholder\":\"e.g. VR, Honda\",\"field_type\":\"text_box\",\"field_name\":\"title\"},{\"label\":\"Audience\",\"placeholder\":\"e.g. Women, Aliens\",\"field_type\":\"text_box\",\"field_name\":\"audience\"},{\"label\":\"Product Description\",\"placeholder\":\"e.g. VR is an innovative device that can allow you to be part of virtual world\",\"field_type\":\"textarea\",\"field_name\":\"description\"}]}', 1, '2026-06-08 13:25:15', '2026-06-08 13:25:15'),
(3, 'name', 'give catchy only name of category  for : ##keywords##  without icon or emojis', 'category', '{\"field\":[{\"label\":\"Seed words\",\"placeholder\":\"e.g.  fast, healthy, compact\",\"field_type\":\"text_box\",\"field_name\":\"keywords\"}]}', 0, '2026-06-08 13:25:15', '2026-06-08 13:25:15'),
(4, 'coupon_name', 'give 1 catchy only name of Offer or discount Coupon  for : ##keywords## ', 'coupan', '{\"field\":[{\"label\":\"Seed words\",\"placeholder\":\"e.g.  fast, healthy, compact\",\"field_type\":\"text_box\",\"field_name\":\"keywords\"}]}', 0, '2026-06-08 13:25:15', '2026-06-08 13:25:15'),
